// Field manual: the real-world knowledge behind each mechanic. Edition basis of the text: NFPA 13-2025,
// NFPA 20, NFPA 25, NFPA 72 (the enforced NFPA 13 edition is a site setting; plan review cites that one).
// Company rules and ASSUMED / NEEDS PE REVIEW values are listed on the 'site' page. Always verify against
// the edition your jurisdiction adopted.
var DI = globalThis.DI || (globalThis.DI = {});
// Pieces built from the engine tables, so the manual never carries its own copy of a number.
DI.MAN = (function () {
  const f = DI.asdFmt, A = DI.AIR_TEST, R = DI.JURIS;
  // the listed range of every aspirating detector model, per stage, with the datasheet it was read from
  const asd = '<table><tr><th>Model</th>' + DI.ASD_STAGES.map(([, n]) => '<th>' + n + '</th>').join('') + '<th>Datasheet</th></tr>' + Object.keys(DI.ASD_MODELS).map((k) => { const M = DI.ASD_MODELS[k];
    return '<tr><td><b>' + M.label + '</b>' + (k === DI.ASD_DEFAULT ? ' (default)' : '') + '<br>' + M.models + '</td>' + DI.ASD_STAGES.map(([s]) => '<td>' + (M.range[s] ? f(M.range[s][0]) + ' to ' + f(M.range[s][1]) : M.fire1Only && s === 'fire1' ? M.pick.map((x, i) => x + ' (' + M.pickName[i] + ')').join(' / ') + ': discrete settings' : DI.VEA_NA) + '</td>').join('') + '<td>' + M.doc + '</td></tr>'; }).join('') + '</table>';
  // the thirteen recovery steps (DI.RECOVERY) with the reason for each
  const why = { 'silence': 'Silence is not reset: it acknowledges the sound and clears nothing.', 'find-head': 'Select it on the map.', 'close-valve': 'The tamper supervisory comes in: expected.',
    'isolate-air': 'The supply to this zone only. Left open, the compressor keeps feeding the open pipe.',
    'drain-zero': 'Wait for the gauge. The game confirms it for you once it reads ' + DI.SAFE_PSI + ' psi or less (ASSUMED) and the pipe is empty. Air out an open drain is air: falling pressure and compressor run time, never water flow.',
    'reset-panel-1': 'So detection drops out and the solenoid de-energizes; the riser reset is refused while it is latched. Not applicable when detection never latched.',
    'replace-head': 'From the spare cabinet. Allowed only with the water isolated, the air / N&#8322; supply isolated, and the pipe at about 0 psi with no water. The drain may stay open: &ldquo;close the drain, then replace the head&rdquo; is backward.',
    'reset-valve': 'Only when the valve tripped. After a trip the clapper is reset <b>before</b> the air is restored: the valve is not set until the clapper is closed, so air restored first is not held and counts for nothing.',
    'drain-close': 'After the riser reset. Air cannot build against an open drain.', 'restore-air': 'Reopen the supply and let it build to normal pressure.',
    'reset-trim': 'The pneumatic actuator re-arms once there is air in the pipe. An electric / electric trim has no actuator: not applicable.',
    'reset-panel': 'After the air is back: clears P and the troubles. Reset earlier and P latches straight back.',
    'open-valve': '<b>Mandatory.</b> Until it is open the building is unprotected. A zone will hold only when the panel is reset with the solenoid de-energized, the clapper is reset, P is clear and the air is above low air: opened earlier, the valve trips again. In the scored drill incident the valve refuses to reopen until then. Anywhere else it opens, and the warning lists what is still open (for example &ldquo;head not replaced in&rdquo; the zone).' };
  const rec = '<ol>' + DI.RECOVERY.map(([k, label]) => '<li><b>' + label.replace('N₂', 'N&#8322;') + '.</b> ' + why[k] + '</li>').join('') + '</ol>';
  const air = A.psi + ' psi air held 24 hours; a loss of ' + A.drop + ' psi or less passes (an end reading of ' + A.endMin + ' psi or more at ' + A.psi + ' psi)';
  const airRef = 'NFPA 13-2025 ' + R['US-2025'].ref.airTest.split(' ').slice(2).join(' ') + '; 2022 ' + R['US-2022'].ref.airTest.split(' ').slice(2).join(' ') + '; 2019 ' + R['US-2019'].ref.airTest.split(' ').slice(2).join(' ');
  const tail = (x) => x.split(' ').slice(2).join(' ');
  const refill = 'NFPA 13-2025 ' + tail(R['US-2025'].ref.refill) + '; 2019 and 2022 ' + tail(R['US-2019'].ref.refill) + ' (an N&#8322;-only source: 2019 and 2022 ' + tail(R['US-2019'].ref.refillN2) + '; 2025 has no separate N&#8322;-only clause, &sect;8.2.7.6 has none, so ' + tail(R['US-2025'].ref.refill) + ' applies to every source: VERIFIED)';
  // the Annex note on a shared supply, and the 60 min allowance for a zone wholly in freezer rooms held below 5 F
  const annex = '2019 and 2022 ' + tail(R['US-2019'].ref.refillAnnex) + '; 2025 ' + tail(R['US-2025'].ref.refillAnnex) + ', which also covers a shared nitrogen source';
  const cold = '2019 and 2022 ' + tail(R['US-2019'].ref.refillCold) + ', N&#8322;-only ' + tail(R['US-2019'].ref.refillN2Cold) + '; 2025 ' + tail(R['US-2025'].ref.refillCold);
  // cause-and-effect matrix: the rows and tags as the matrix itself lists them (cause.js)
  const ceRows = '<table><tr><th>Input row</th><th>Tag</th></tr>' + DI.CE_ROWS.map((r) => '<tr><td>' + r.label + '</td><td>' + r.tag + '</td></tr>').join('') + '</table>';
  // supervising-station paths: when a dead panel is annunciated, with the section per edition
  // (the NFPA 72 edition is its own site setting: the table gives all three)
  const t72 = (yr, k) => DI.REF72[yr][k].replace(/^NFPA 72-\d+ /, '');
  const paths = '<table><tr><th>Path to the supervising station</th><th>Dead panel annunciated after</th><th>NFPA 72-2025</th><th>NFPA 72-2022</th><th>NFPA 72-2019</th></tr>' + Object.keys(DI.COMM_PATH).map((k) => { const q = DI.COMM_PATH[k];
    return '<tr><td>' + q.label + (k === DI.COMM_DEFAULT ? ' (default)' : '') + '</td><td>' + DI.delayText(q.delay) + '</td><td>' + t72(2025, q.ref) + '</td><td>' + t72(2022, q.ref) + '</td><td>' + t72(2019, q.ref) + '</td></tr>'; }).join('') + '</table>';
  // NAC voltage drop: the calculation, its basis labels by edition and the worked example of the acceptance test
  const nacEx = (function () { const iTot = 7 * DI.NAC_CD[75], R = 2 * 600 * DI.NAC_OHM[12] / 1000, v = DI.NAC_V_END - iTot * R; return { iTot, R, drop: iTot * R, v, m: (v - DI.NAC_VMIN) / DI.NAC_VMIN * 100, max: (DI.NAC_V_END - DI.NAC_VMIN) / (iTot * 2 * DI.NAC_OHM[12] / 1000) }; })();
  const sec = (s) => s.replace(/§/g, '&sect;');
  const nac = '<h4>NOTIFICATION CIRCUIT VOLTAGE DROP (NAC), A PLAN REVIEW CHECK</h4><p>One DC notification appliance circuit per panel, <b>Class B, end-line-loaded</b>: every appliance is taken at the far end of the run, the conservative screen. It is <b>off by default</b>; switch it on at the panel and pick the wire gauge (' + DI.NAC_AWG.join(' / ') + ' AWG), the routed one-way length, the number of appliances, their candela and the start voltage. ' +
    'The check is the voltage at the last appliance: <b>V at the last appliance = start voltage &minus; total current &times; circuit resistance</b>, with total current = appliances &times; the current of one at its minimum voltage, and <b>circuit resistance = 2 &times; one-way length &times; ohm per 1000 ft &divide; 1000</b>. Both conductors are counted through the length; the table resistance itself is used as printed (NFPA 72-2025 &sect;18.3.7.3).</p>' +
    '<table><tr><th>Item</th><th>Value</th><th>Label</th></tr><tr><td>Wire resistance, ohm per 1000 ft</td><td>' + DI.NAC_AWG.map((a) => a + ' AWG ' + DI.NAC_OHM[a]).join(', ') + '</td><td>' + DI.NAC_WIRE + '. On a NEC 2026 site: ' + DI.NAC_WIRE_2026 + '</td></tr>' +
    '<tr><td>Appliance minimum voltage</td><td>' + DI.NAC_VMIN + ' V</td><td>A.18.3.7 [HB]; ASSUMED, confirm on the listing</td></tr><tr><td>Appliance current at the minimum voltage</td><td>' + DI.NAC_CDS.map((c) => c + ' cd ' + DI.NAC_CD[c].toFixed(2) + ' A').join(', ') + '</td><td>ASSUMED listing values: round numbers, not from a listing</td></tr>' +
    '<tr><td>Start voltage</td><td>' + DI.NAC_VSTART.filter(Boolean).map((v) => v.toFixed(1)).join(' / ') + ' V, or not given</td><td>the panel or module start terminal voltage from its data sheet (ASSUMED picks); not given, ' + DI.NAC_V_END + ' V is used: end of discharge on a 24 V system, ASSUMED</td></tr></table>' +
    '<p><b>Verdicts</b>, one finding per panel, the worst of: <b>FAIL</b> below the appliance listed minimum of ' + DI.NAC_VMIN + ' V; <b>warning, THIN</b> when the margin above the minimum is under ' + DI.NAC_THIN * 100 + ' percent (company rule: PRACTICE, NEEDS PE REVIEW); <b>warning, not a fail,</b> when the start voltage is ASSUMED. A clean pass is one information line: it is the NAC voltage drop calculation that the documentation list asks for (&sect;7.2.1(8) [CODE], 2019, 2022 and 2025). The panel also shows the longest one-way length that still passes. ' +
    'Worked example: 7 appliances of 75 cd on 600 ft of 12 AWG from ' + DI.NAC_V_END + ' V: ' + nacEx.iTot.toFixed(1) + ' A, ' + nacEx.R.toFixed(3) + ' ohm, a drop of ' + nacEx.drop.toFixed(2) + ' V, <b>' + nacEx.v.toFixed(2) + ' V</b> at the last appliance, a margin of ' + nacEx.m.toFixed(1) + ' percent: no fail, a THIN warning, and the longest passing length is ' + (Math.floor(nacEx.max * 10) / 10).toFixed(1) + ' ft.</p>' +
    '<p><b>Basis by NFPA 72 edition.</b> 2025: ' + sec(DI.REF72[2025].nacVd) + ' (end-line-loaded: A.18.3.7.4 [HB]). 2022: ' + sec(DI.REF72[2022].nacVd) + '. 2019: ' + sec(DI.REF72[2019].nacVd) + '. On the hidden Canadian row the check is not evaluated: ' + DI.NAC_CA_HOLD + ' The NEC edition is a site setting (2023 by default); NEC 2026 Table 8 is on hold.</p>' +
    '<p><b>What it is not.</b> It is a plan review check only. It raises no signal, has no matrix row and never touches release, detection, the P latch, the hooks or the standby battery calculation (the alarm load of the battery stays a listing pick). Point-to-point, Class A, module voltage adjustment, sync-module loss and speaker circuits are not modelled.</p>';
  // DACT sections per edition: the channel-failure rule and the test interval
  const dact = { chan: '2019 ' + t72(2019, 'dactChan') + '; 2022 and 2025 ' + t72(2025, 'dactChan'), test: '2019 ' + t72(2019, 'dactTest') + '; 2022 and 2025 ' + t72(2025, 'dactTest'),
    tries: '2019 ' + t72(2019, 'dactTry') + '; 2022 and 2025 ' + t72(2025, 'dactTry') };
  // the standby reference table, from the function the dialog uses (default site: NFPA 72-2025)
  const stby = '<table><tr>' + DI.STBY_COLS.slice(0, 4).map((c) => '<th>' + c + '</th>').join('') + '</tr>' + DI.standbyTable(new DI.World(4, 4)).map((r) => '<tr><td>' + r.label + (r.sel ? '' : ' (reference only)') + '</td><td>' + r.standby + '</td><td>' + r.alarm + '</td><td>' + r.tag.replace(/§/g, '&sect;') + '</td></tr>').join('') + '</table>';
  // the signal schedule at the default classes, from the same function the dialog uses
  const sched = '<table><tr>' + DI.SCHED_COLS.map((c) => '<th>' + c + '</th>').join('') + '</tr>' + DI.signalSchedule({ cfg: {} }).map((r) => '<tr>' + [r.label, r.class, r.ss, r.fd, r.tag].map((c) => '<td>' + String(c).replace(/&/g, '&amp;') + '</td>').join('') + '</tr>').join('') + '</table>';
  return { asd, rec, air, airRef, refill, annex, cold, ceRows, paths, dact, stby, sched, nac, src: DI.ASD_SRC };
})();
DI.MANUAL = [
  { id: 'play', t: 'How to play', h: `<p>You are the fire protection designer, the commissioning tech and the night operator. Every contract is the same loop: <b>build</b> it, <b>prove</b> it with tests, then <b>survive</b> the drill.</p>
<table><tr><th>Key</th><th>Does</th></tr><tr><td>Q</td><td>Select / operate</td></tr><tr><td>1</td><td>Main pipe (drag). Drag over pipe to resize it</td></tr><tr><td>2</td><td>Sprinkler branch lines (drag a rectangle). R flips direction</td></tr>
<tr><td>3 / 4 / 5 / X</td><td>Single head / air tubing / wiring / erase</td></tr><tr><td>[ &nbsp;]</td><td>Pipe size</td></tr><tr><td>R</td><td>Rotate part</td></tr><tr><td>Space</td><td>Pause</td></tr><tr><td>Ctrl+Z</td><td>Undo</td></tr><tr><td>Right-drag, WASD, wheel</td><td>Pan and zoom</td></tr><tr><td>G / M</td><td>Goals / this manual</td></tr></table>
<p><b>One tile is 10 ft.</b> One sprinkler tile protects 100 ft&sup2;. Branch lines only connect end to end, and to a main beside them. Mains connect to everything they touch.</p>
<p>Pipe colour is what is inside it: blue is water (brighter is higher pressure), sand is compressed air, teal is nitrogen. White dashes are flow. Hover any pipe for pressure, flow and velocity.</p>
<p>Select a riser or pump to operate it and run its tests. <b>Review</b> is the plan checker. <b>Skip</b> jumps ahead in time and stops if an alarm comes in.</p>` },
  { id: 'calls', t: 'Field calls (find the fault)', h: `<p>A field call is a small puzzle on an installation that already exists. You get a symptom, the records, a small repair budget and one central question. The plant is the same simulation as the contracts: nothing is scripted except the fault.</p>
<p><b>Starting states.</b> Inherited installation (it has been like this for a while), nearly finished plant (the contractor says it is done), records-only investigation (something happened last night; the log and the test records are your evidence) and active incident (it is going wrong right now).</p>
<p><b>Hints</b> come one at a time: the system to look at, a measurement to take, then the fault itself. The camera goes to each one. <b>Diagnose</b> answers the central question; a wrong pick is answered with why it is not that, and counted.</p>
<p><b>Scoring.</b> One star for the fix (every goal, the diagnosis included). One for the fewest edits at no more than the cheapest fix costs. One for a diagnosis right the first time, at most one hint, no more time out of service than par, and, where the call has a live cause, no panel reset made while it was still live.</p>
<ul><li><b>An edit</b> is a change to the layout against the starting state: a pipe tile added, removed, resized or re-laid; a cap; a tile of air tubing; a part added, removed, replaced or turned end for end; a wire; a design setting on a part (a pump or jockey setting, a trim setpoint, a tamper switch fitted). Dropping a valve into a pipe run is one edit.</li>
<li><b>Not an edit:</b> operating the plant. Opening or closing a valve, a pump's mode, stopping a pump, resetting a station or the panel, running a test.</li>
<li><b>Out of service</b> is game time with a control valve not fully open, a fire pump out of AUTO (not on its own test), a dry or preaction zone not set and pressurized or with P latched, or an isolated air supply. Pause (Space) while you think; time spent paused costs nothing.</li></ul>
<p><b>Variants.</b> Each call has two or three. They move the fault, change the supply, the layout or what else is going on, and the later ones combine ideas from earlier calls. Switching variant starts it fresh.</p>
<p><b>Afterwards</b> the report compares three fixes side by side: yours, the cheapest one and an easily maintained one, each drawn with its edits ringed (red where something was taken away), with its cost and what it teaches.</p>
<p><b>Tools that matter here.</b> <b>Turn end for end</b> (select an inline part: a check valve, a pump, a backflow preventer, a control valve) reverses it in place for free. A cap shows as a short yellow bar across a joint, also where a pipe meets a part. A control valve can have <b>no tamper switch fitted</b> (an old sealed yard valve): closing it signals nothing until a switch is fitted and wired. A pump suction gauge cannot read below a full vacuum: the game shows a starved suction as -14.7 (full vacuum).</p>
<p><b>Drills keep the commissioning record.</b> In a contract the goals are recorded when the acceptance drill starts. What was proved before the fire (a quiet half hour on the jockey, a refill, a passing calc) stays proved while the drill runs the plant hard.</p>` },
  { id: 'wet', t: 'Wet pipe systems', h: `<p>Pipe full of water under pressure, closed heat-activated sprinklers. Only the sprinklers that get hot open. Wet is the default: it is the most reliable and it puts water on the fire soonest.</p>
<ul><li><b>Limits:</b> the whole system must stay at 40&nbsp;&deg;F or above. One riser may protect 52,000 ft&sup2; per floor for light and ordinary hazard (NFPA 13-2025 &sect;4.4.1).</li>
<li><b>Riser:</b> control valve with tamper switch, alarm check valve or riser check with a waterflow switch, main drain, gauges above and below.</li>
<li><b>Waterflow alarm:</b> a vane switch has a retard (typically 30&ndash;45 s) so pressure surges do not send the fire department. NFPA 72 wants the signal within 90 s of a flow equal to one sprinkler; NFPA 13 allows 5 minutes for the local alarm.</li>
<li><b>Inspector&rsquo;s test:</b> an orifice equal to the smallest sprinkler, at the remote end. It proves the alarm works with one head flowing.</li>
<li><b>Main drain test:</b> ${DI.MDT_LINE.replace('Company practice. Main drain test: w', 'W')} The code rule (VERIFIED): ${DI.REF25.mainDrain.replace(/§/g, '&sect;')}. In the Tutor&rsquo;s words: &ldquo;${DI.REF25.passLine.replace(/§/g, '&sect;')}&rdquo; A drop over 10 percent is a trigger to investigate, not an automatic fail: the result reads <b>INVESTIGATE</b>. The code says <b>full flow pressure</b>; the report labels it &ldquo;Full-flow (residual)&rdquo;. The main drain is on the supply side of the valve: on a dry or preaction riser it flows supply water and never bleeds system air.</li></ul>
<p><b>Why not in a data hall?</b> A wet system has one failure mode the owner cannot accept: a single broken or leaking sprinkler puts water on live equipment immediately.</p>` },
  { id: 'dry', t: 'Dry pipe systems', h: `<p>For spaces that freeze: docks, canopies, unheated mechanical yards. The pipe holds compressed air or nitrogen. A <b>differential dry pipe valve</b> has a clapper with a large air seat and a small water seat, so a little air holds back a lot of water, roughly 5.5 to 1.</p>
<ul><li><b>Trip point</b> &asymp; water pressure &divide; 5.5. Air is normally set about 20 psi above it. Remember that a fire pump raises the water pressure, and so the trip point.</li>
<li><b>The delay is the problem.</b> Air must bleed down to the trip point, then water has to push the rest of the air out through one sprinkler.</li>
<li><b>Size limits (NFPA 13-2025 &sect;8.2.4.2, .2.1 and .2.2; in 2019 and 2022 &sect;8.2.3.2 to &sect;8.2.3.4):</b> up to 500 gal needs no delivery test; up to 750 gal with a listed quick-opening device (accelerator). Above that, water must reach the inspector&rsquo;s test in 60 s. The calculation / table route (2025 &sect;8.2.4.3.1 and Table 8.2.4.3.2; 2019 and 2022 Table 8.2.3.6.1: light 60, ordinary 50, extra 45, high-piled storage 40 s) is shown on the test report for information and is not modelled.</li>
<li><b>Zone volume is what counts:</b> pipe plus a fittings allowance plus the valve trim (5 % and 2 gal by default, both ASSUMED project settings). The valve and the trip-test report show the pipe-only figure beside it. A system that reads 498 gal of pipe is a 525 gal zone.</li>
<li><b>Insurer overlay:</b> where the site insurer is FM, dry and double-interlock systems must deliver in 30 s at any volume (FM DS 5-32, NEEDS PE REVIEW). The most stringent limit governs, and the report shows the NFPA limit, the FM limit, the governing one and the margin in seconds.</li>
<li><b>Design area +30%</b> with no density reduction, because the fire is bigger when the water arrives (Ch. 19).</li>
<li><b>No gridding</b> (&sect;8.2.1). Air cannot be swept out of a loop.</li>
<li><b>C-factor 100.</b> Company rule for all sprinkler pipe. Nitrogen protects the pipe and earns no C-factor credit.</li>
<li><b>Air supply</b> must restore normal pressure in 30 minutes (${DI.MAN.refill}). The requirement is <b>per system</b>, and the <b>code check</b> is the largest single zone on the supply, filled <b>alone</b> with the full capacity from 0 psig, in 30 minutes or less. Each dry and preaction valve also shows two <b>measured</b> readings, <b>First fill (commissioning)</b> and <b>Last refill</b>: the clock runs from the first gas into the closed-up zone to normal pressure. They are informational and never read FAIL: each row reads &ldquo;12.2 min (measured, informational)&rdquo;, with no limit, no verdict and no colour at any length, because a measured time is never compared with the limit as if it were the code check (FP Lead, Cycle 8). The code check is the <b>Air supply sizing</b> row under them. Zones on one compressor fill at the same time in this game (${DI.PARALLEL_SPLIT}), so a shared fill can run past 30 minutes while the code check passes. A zone that lost its air without tripping starts an informational timer at the low-air crossing. The 2025 acceptance wording (&sect;29.2.3.2.4.1) measures the time to set pressure from the opening of the air supply (from a search, not verbatim: VERIFY). Refrigerated spaces maintained below 5&nbsp;&deg;F get 60 minutes instead of 30 (${DI.MAN.cold}; VERIFIED). <b>It is per zone</b>: ${DI.COLD_NOTE} A zone gets 60 minutes only when <b>every</b> room it protects is a <b>Refrigerated Space</b> room with &ldquo;held below 5 F&rdquo; set (that &ldquo;every room&rdquo; reading is ASSUMED, NEEDS PE REVIEW and AHJ). The room type alone never qualifies: a cooled space that is not held below 5&nbsp;&deg;F (a 35&nbsp;&deg;F dock, for example) still gets 30, and so does a zone that also covers any other room. A typical hyperscale data center has no space below 5&nbsp;&deg;F, so the default is 30 minutes everywhere; the exception is narrow on purpose. It moves that zone&rsquo;s clock, sizing minimum and review text together. A save made with the old site-wide setting loads with every zone back at 30 minutes and says so once in the log. Some owners or FM jobs set a tighter refill time. Check the project basis of design. The <b>owner / insurer refill target</b> is an optional site setting (${DI.OWNER_REFILL.filter(Boolean).join(' / ')} min, ASSUMED picks; none by default). It is judged the way the code check is, on the largest zone alone from 0 psig (that method is ASSUMED, unless the owner defines it differently). A fill longer than the target but inside the code limit is a plan review <b>warning tagged owner/insurer criterion</b>, not a code failure (the warning tier is PRACTICE); over the code limit it stays the code FAIL, with no second finding. A target at or above the code limit is no tighter than the code and raises nothing.</li>
<li><b>Air refill order</b> (site setting, PRACTICE, off by default). Off, every zone on a shared compressor fills at the same time. On, <b>largest zone first</b>: the compressor serves one calling zone at a time, the largest zone volume first, ties by the lowest zone number. <b>The code check does not change</b>: the largest zone alone, from 0 psig, at full capacity, in 30 minutes or less. When the sequence takes longer than that in total but every zone alone is inside it, the report says: &ldquo;PASS: each zone restores in 30 min or less when filled alone (largest X min). The sequential campus refill total of Y min is informational and not a code limit.&rdquo; An owner target for the sequence total is not modelled: the owner / insurer refill target is judged on the largest zone alone.</li>
<li><b>Sizing the compressor.</b> scfm minimum = zone volume in cubic feet &times; (pressure &divide; 14.7) &divide; 30, taken on the <b>largest</b> zone the compressor serves (one compressor serving several systems is sized on the single largest system: Annex ${DI.MAN.annex}). <b>With an AVC (air maintenance device) regulating, the pressure is the zone&rsquo;s normal set point</b> and the compressor cut-out does not enter the sizing. Only on a compressor direct to the system (no AVC, the small-compressor case) is it the normal or the cut-out if that is higher, and there a cut-out above the zone&rsquo;s high-air supervisory is a plan review <b>fail</b>: the compressor can push the zone into high air (ASSUMED practice, NEEDS PE REVIEW). The cut-out is a compressor setting, ASSUMED, none by default. For a zone wholly in freezer rooms held below 5&nbsp;&deg;F the 30 becomes 60. The formula is an ideal-gas screen, not a quoted NFPA equation. A 525 gal zone is 70.2 ft&sup3;; at 40 psi it needs about 6.4 scfm, about 8 with a &times;${DI.AIR_SIZING.margin} margin, so 10 scfm is reasonable and fills that zone alone in about 19 minutes. Below the bare minimum plan review <b>fails</b> the design: the supply cannot restore the largest zone in 30 minutes even filling it alone. Between the minimum and the margin it warns (the &times;${DI.AIR_SIZING.margin} margin is ASSUMED practice, NEEDS PE REVIEW, not an NFPA factor). <b>Recovery time is mostly compressor time</b>: the operator&rsquo;s own steps take seconds or minutes, the refill takes the rest. Use <b>Skip the refill</b> on the valve to jump to the end of it.</li>
<li>Low-air and high-air supervisory setpoints are set on each valve (30 and 50 psi around a 40 psi normal by default).</li>
<li><b>The AVC and the air supply valve are two devices.</b> The supply valve shuts the air to the zone; the AVC (air maintenance device) regulates it at normal pressure and has a bypass. &ldquo;AVC in auto&rdquo; means the supply valve <b>open and</b> the bypass <b>closed</b>. With the bypass open nothing regulates: the zone climbs toward <b>what the compressor can deliver</b> (ASSUMED): its cut-out where one is set, else its <b>rated max discharge or its relief setpoint, whichever is lower</b>; where the compressor is not modeled, ${DI.AVC_BYPASS_PSI} psi (ASSUMED). It is never the 40 psi test pressure. HIGH AIR at the high setpoint comes in on the way and is the main signal. ${DI.AVC_NOTE} An open bypass is an impairment tag on the riser. A <b>tamper switch on the bypass</b> is optional, per zone, off by default: ${DI.AVC_TAMPER_TAG}. Fitted, an open bypass is also a supervisory signal at the panel and a row in the matrix; it is never a release input. The trim bleed on the valve brings a high zone back to normal. Plan review raises two <b>warnings on a compressor&rsquo;s relief setpoint</b> (FP Lead, Cycle 8; PRACTICE checks on ASSUMED picks, never a fail): a relief <b>at or below the cut-out</b>, or at or below the high-air setpoint of a zone the compressor feeds, will lift during normal operation; and a relief <b>above the rated max discharge</b>. The drift rule does not change: a cut-out still rules over a lower relief, and the first warning is the flag for that configuration. The picks are ASSUMED; on a real job the values come from the selected unit.</li>
<li><b>Acceptance air test (dry and double interlock):</b> ${DI.MAN.air}. A loss over 1.5 psi must be corrected. The NFPA text names 40 psi for 24 hours; the game tests at the <b>greater of 40 psi or the zone&rsquo;s normal pressure</b> (company practice, NEEDS PE REVIEW), so a zone with a 50 psi normal is tested at 50 and passes at 48.5 or more, and a normal below 40 still tests at 40. The test starts at test pressure: a zone sitting lower is charged first (the game does this for you, a simplification), and a zone sitting above it has to be bled at the trim. The report gives the test pressure, the start and end readings, the pass line with its section, and the drop. Section: ${DI.MAN.airRef} (verified in all three editions). After the test the supply is restored and the zone goes back to its <b>normal set point</b>. Where the pipe is left above normal (a normal below 40 psi), bleed it at the <b>trim air / test bleed</b>, not at the main drain, and never by opening the control valve: that is the water side. Where it is below normal, leave the supply open and it refills. Then confirm, <b>all</b> of: pressure in the normal band, above low air and above the P release set point with margin; <b>the P latch reset</b> (at the releasing panel on electric / electric, at the trim on electric / pneumatic); no air supervisory in (low air, high air); the AVC in auto (supply valve open, bypass closed); the control valve normal; and <b>every drain closed</b>. HIGH AIR shows while the pipe is above the high-air setpoint. The 1.5 psi pass line is an absolute value at every test pressure.</li>
<li><b>Return to normal, and the Finish button</b> (company practice, ASSUMED: NFPA 13 prescribes no bleed point). After the 24 h air test the zone goes back to its normal set point and the operator ends the step with <b>Finish return to normal</b> on the valve. Nothing ends it by itself: when every condition holds the valve only says &ldquo;${DI.RT_READY}&rdquo; Finish is accepted with the pressure in the normal band, above low air and above the P set point, P reset, no supervisory active (low air, high air, AVC bypass, control valve off normal), the supply open and every drain closed. Pressed sooner it is refused, every time, with the text: &ldquo;${DI.RT_EARLY[0]}a drain is open; P is still latched${DI.RT_EARLY[1]}&rdquo; A refusal counts as <b>one error for each unchanged set of blockers</b> (FP Lead, Cycle 8, PRACTICE): pressing again with the same things missing, or with fewer, adds no error; a blocker that was not in the last refusal does, and so does one that comes back after the zone was ready. The raw number of presses is shown beside the errors as information, not as errors: &ldquo;${DI.rtPressLine(3, 1)}&rdquo;</li>
<li><b>Drains during the return to normal.</b> Nothing is blocked; the consequence is modelled. The <b>main drain</b> is on the supply side of the clapper: it never bleeds system air, and with the control valve open it is a main drain flow test, so supply water flows and the system gauge does not move. The <b>system drain</b> is downstream: it does bleed air, fast and coarse, so it overshoots. Opening either one gets one line of coaching: &ldquo;${DI.RT_COACH}&rdquo; Closed again before anything comes of it, that is all, also while the pressure is passing through the normal band. A real consequence is <b>one scored error per event</b>, in plain words on the result (the Fire Tutor&rsquo;s sentences): &ldquo;${DI.RT_LOW_DRAIN}&rdquo; Where no drain was open the low-air text is &ldquo;${DI.RT_LOW_NODRAIN}&rdquo; (ASSUMED wording), and where the air supply was isolated at the event either one adds: &ldquo;${DI.RT_ISO.trim()}&rdquo; &ldquo;${DI.RT_TEXT['p-latch']}&rdquo; &ldquo;${DI.RT_TEXT['main-drain-flow']}&rdquo; And if the valve trips: &ldquo;${DI.RT_TEXT['water-flow']}&rdquo; An overshoot that latched P is not put right by refilling into the band: P has to be reset before Finish. A clean pass reads: &ldquo;${DI.RT_CLEAN}&rdquo; The score does not depend on game speed: it reads the lowest pressure of each step, and while a system drain is letting air out the step is split into ${DI.RET_SUBSTEP} s pieces (SIMPLIFICATION). The valve files a <b>Return to normal</b> result with one line per error, and a drill report lists the same lines. It is practice: never a contract goal, never a contract star.</li>
<li><b>Loss of supply air</b> is a trouble of its own: every compressor or nitrogen source on the zone has lost power or failed. It arrives beside the low-air supervisory, which only says the pressure is down. Shutting the zone&rsquo;s own supply valve on purpose does not raise it.</li>
<li><b>A closed air supply valve is an impairment:</b> tag it and restore it. It is not a supervisory signal here. The game shows it as an amber <b>IMPAIRMENT TAGS</b> strip above the annunciator and a line on the valve, with or without a live panel. Cause first, symptom second: the low-air supervisory still comes in only when the gauge actually falls.</li>
<li>Pipe is pitched back to drain; low points get drum drips that someone has to empty before winter.</li></ul>
<p>A dry system does <b>not</b> protect against accidental discharge. Break a sprinkler and the valve trips.</p>` },
  { id: 'pre', t: 'Preaction systems', h: `<p>A deluge-type valve, closed sprinklers, supervisory gas in the pipe and a detection system. This game builds one kind only: <b>double interlock</b>. Water enters the pipe when two things are both true.</p>
<table><tr><th>Leg</th><th>True when</th><th>Held by</th></tr><tr><td><b>D</b> detection</td><td>aspirating detection is at or above <b>Fire 1</b> (a level check, so a jump straight to Fire 2 is D), or one listed spot detector alarms in an electrical / UPS room, or someone operates a manual release station wired to the panel (typed DETECTION)</td><td>a latch in the releasing panel</td></tr>
<tr><td><b>P</b> pressure</td><td>pipe pressure falls below the <b>P trip</b> setpoint</td><td>a latch, until someone resets it where that trim holds it</td></tr></table>
<p><b>Release = D AND P.</b> A broken sprinkler alone gives P and no water. A false detection alone gives D and no water.</p>
<p>The full formula has a second path that is off unless the project turns it on: <b>Release = (D AND P) OR (bypass 9(c) AND Manual Release zone)</b>, the second term on an electric / electric trim only. The valve&rsquo;s inspector names the path in its <b>Release path</b> row:</p>
<table><tr><th>Release path row</th><th>Means</th></tr><tr><td>(D AND P) armed</td><td>normal: water needs both legs</td></tr><tr><td>Manual Release zone BYPASS ARMED (9(c), NEEDS PE REVIEW)</td><td>the project flag is ON on this electric / electric valve and the zone is idle</td></tr>
<tr><td>Manual Release zone RELEASING - without P</td><td>the zone has latched its own release. D reads normal, by design: the zone is not detection</td></tr></table>
<ul><li><b>P is a threshold, not a cause.</b> The sensor reads pipe pressure and nothing else. An open sprinkler, an open inspector&rsquo;s test and a broken pipe all look the same to it: any opening big enough to beat the compressor. A slow leak the compressor keeps up with never reaches P trip and gives a low-air supervisory only.</li>
<li><b>The trim decides the sensor, the solenoid and the reset.</b>
<table><tr><th>Trim</th><th>P sensed by</th><th>Solenoid energized on</th><th>Valve opens on</th><th>P is reset</th></tr><tr><td>Electric / electric</td><td>pressure switch PSL-REL, latched in the panel</td><td>D AND P</td><td>D AND P</td><td>at the releasing panel</td></tr>
<tr><td>Electric / pneumatic</td><td>pneumatic actuator PA-REL, at the valve</td><td>D alone</td><td>D AND P</td><td>at the actuator, at the trim</td></tr></table></li>
<li><b>Resetting.</b> A panel reset clears the panel&rsquo;s latches and then reads every input again, so a live input comes straight back. On electric / electric, P clears with the panel reset once the pipe is back above P trip; reset earlier and it latches again. On electric / pneumatic a panel reset cannot clear P: restore the air, then reset the actuator at the trim. On both trims a tripped valve is reset by hand at the riser, a panel reset never closes it, and the riser reset never clears P.</li>
<li><b>Setpoints live on each valve</b> and load from the maker trim preset. The order is always high-air supervisory &gt; normal &gt; low-air supervisory &gt; P trip, with low air at least 5 psi above P trip so the warning arrives first. Defaults are 50 / 40 / 30 / 20 psi. All of these numbers are ASSUMED and adjustable.</li>
<li><b>Low air and high air are supervisory only.</b> They follow live pressure and never release anything. P latches: it stays true after the air comes back, until it is reset.</li>
<li><b>A latched P on the annunciator</b> is a release input whose signal class has not been elected. It shows as an OPEN item, and the class is a site setting: alarm or trouble if the engineer elects one, never supervisory (NEEDS PE REVIEW).</li>
<li>Double interlock is treated like dry pipe for delay: <b>+30% design area, no gridding</b>, and the <b>60 s timed trip test above 500 gal of zone volume</b> (NFPA 13-2025 &sect;8.3.2.3.1.1). A quick-opening device may help meet the 60 s but does not extend the 500 gal: there is no 750 gal exemption for double interlock. Minimum <b>7 psi</b> supervisory pressure.</li>
<li><b>Panel failure never releases water.</b> The solenoid is energize-to-release. The releasing panel runs on standby batteries when utility power fails (24 h of standby plus 5 minutes of alarm on the default basis; see &ldquo;Battery and standby&rdquo; under Detection and signals). On battery it still alarms and releases. It shows AC failure at the panel at once and transmits it to the supervising station after the site&rsquo;s delay (60 to 180 minutes). LOW BATTERY comes in at the battery&rsquo;s listed low-voltage setpoint, ${DI.LOWBATT_V} V on a 24 V system (ASSUMED, NEEDS PE REVIEW): the code sets no low-battery voltage. Neither the battery, the charger nor the DACT is an input of the release: release = (D AND P) does not depend on any of them. A dead panel leaves the valve shut. Recovery is the mechanical emergency release by a person.</li>
<li><b>A dead panel is dark.</b> No display, no LEDs, nothing to silence and nothing to reset: the buttons say so. The status bar reads PANEL DEAD at once, because you can see the dark panel. The supervising station cannot: it annunciates the loss of communication only after its supervision interval (60 minutes on a single IP path, a site setting), and only then does that line appear on the annunciator. On the valve, the rows the panel feeds read <i>not displayed: panel dead</i>. What is left is mechanical: the gauges, the valve itself, and on an electric / pneumatic trim the actuator&rsquo;s own P.</li>
<li><b>Power coming back is not a release; the inputs are.</b> On an electric / electric trim the P latch lives in the panel&rsquo;s memory, so a dead panel holds none (ASSUMED simplification: lost and re-read, not stored). When power returns the panel reads its inputs again: P comes back on the spot if the pipe is still below P trip, and D if detection is still reading Fire 1. If both are true the valve trips, as it should.</li>
<li><b>Mechanical emergency release.</b> A hand valve at the trim that opens the preaction valve directly, outside the panel logic. No detection and no P are needed. The sprinklers are still closed, so water flows only where a sprinkler is open.</li>
<li><b>Manual station.</b> A manual release station is a device wired to the releasing panel. It is typed DETECTION: it sits inside D for every preaction valve that protects the room it is in, and water still needs P. It stays operated until it is reset at the station. A Manual Release zone that bypasses P is a per-project setting, OFF by default, and NEEDS PE REVIEW (owner/insurer exception, footnote 9(c)). It is a separate release path, not detection: it does not latch D, and it latches its own release, which stays latched after the station is reset until the panel is reset. In a contract an ON bypass is an impairment: a supervisory on the panel and a tag on the valve.</li></ul>
<p><b>The trap:</b> low air alone is supervisory, and it is the operator&rsquo;s window: it arrives above P trip. A slow air loss that is left alone reaches P trip and latches P, because the sensor reads pressure, not the rate of decay. With P latched (broken head, broken pipe, big leak, an unattended slow leak) any detection event trips the valve and the pipe fills. If a head is open or broken it discharges. If every head is closed the zone is water-filled and nothing discharges: that is a recovery event, not a discharge. Drain it, reset it, check for freeze and corrosion exposure, and fix the air supply. So after every repair restore the air and then reset P. A pipe break plus a detection event floods the room. A panel left latched in Fire 1 leaves only P between the pipe and the water.</p>
<p style="color:#7f93a3">Comparison only: NFPA 13 &sect;8.3 also defines single interlock (detection alone admits water) and non-interlock (detection or pressure loss) preaction. They are not built here.</p>` },
  { id: 'gas', t: 'Air, nitrogen and corrosion', h: `<p>Steel + water + oxygen = rust. Dry and preaction pipe is never really dry: hydrotests and trip tests leave water in the low points, and compressed air keeps delivering fresh oxygen at 21%. The result is pinhole leaks at the water line, usually within 5 to 10 years, and a compressor that never stops.</p>
<ul><li><b>Nitrogen generators</b> (membrane or PSA) supply 98%+ nitrogen. With oxygen under about 2% the reaction starves.</li><li>The oxygen already in the pipe has to be <b>purged</b>. A vent at the far end bleeds gas while the generator makes it up (&ldquo;fill and purge&rdquo;); an analyzer closes it at 98%. Expect one to two weeks. Without a vent, dilution relies on leakage and takes months.</li>
<li>Generators are small. The 30-minute fill is usually done by an air compressor, with nitrogen taking over for maintenance.</li>
<li><b>Symptoms to read:</b> compressor run time creeping up, low-air supervisories at night when the pipe cools, a failed 24-hour air test.</li></ul>` },
  { id: 'pump', t: 'Fire pumps', h: `<p>A fire pump adds pressure. It does not make water. NFPA 20 fixes the shape of the curve:</p>
<table><tr><th>Point</th><th>Flow</th><th>Pressure</th></tr><tr><td>Churn (shutoff)</td><td>0</td><td>no more than 140% of rated</td></tr><tr><td>Rated</td><td>100%</td><td>100%</td></tr><tr><td>Overload</td><td>150%</td><td>at least 65%</td></tr></table>
<ul><li>Pick the pump so the system demand lands between about 90% and 140% of rated flow. Never design beyond 150%.</li><li>System components must be rated for <b>churn + maximum suction pressure</b>.</li><li>Suction pressure must stay at or above 0 psi at 150% flow.</li>
<li><b>Electric:</b> listed controller, starts on pressure drop, runs until stopped by hand. Needs a reliable source; otherwise a second source or a second driver.</li><li><b>Diesel:</b> fuel tank 1 gal per hp + 5% expansion + 5% sump, kept at least two-thirds full; two battery sets; engine block heater.</li>
<li><b>Weekly / monthly churn run</b> (NFPA 25): diesel 30 minutes weekly. Electric 10 minutes, weekly when it draws from a ground-level tank.</li><li><b>Annual flow test</b> through the test header: churn, 100%, 150%. Acceptance is at least 95% of the rated curve.</li>
<li>The pressure <b>sensing line</b> connects downstream of the pump&rsquo;s discharge check valve, one per pump.</li></ul>
<p><b>Tank:</b> the pump sets pressure, the tank sets time. Size it for sprinkler demand plus hose stream for the duration: 30 min light hazard, 60&ndash;90 ordinary, 90&ndash;120 extra.</p>` },
  { id: 'set', t: 'Jockey pump and pressure settings', h: `<p>Every piping system leaks a little. Without a jockey (pressure maintenance) pump, system pressure sags until the fire pump starts, and a fire pump start is an alarm.</p><p>NFPA 20 Annex A.14.2.6 gives the usual ladder:</p>
<table><tr><th>Setting</th><th>Value</th></tr><tr><td>Jockey <b>stop</b></td><td>fire pump churn pressure + minimum static suction pressure</td></tr><tr><td>Jockey <b>start</b></td><td>at least 10 psi below jockey stop</td></tr><tr><td>Fire pump <b>start</b></td><td>5 psi below jockey start</td></tr><tr><td>Each additional pump</td><td>10 psi lower again</td></tr></table>
<p>Example: 100 psi pump, churn 120, tank suction 10 &rarr; jockey stop 130, jockey start 120, fire pump 115, lag pump 105.</p><p>If the jockey cycles every few minutes there is a real leak. Find it; do not widen the band.</p>` },
  { id: 'hyd', t: 'Hydraulics', h: `<p><b>Sprinkler:</b> Q = K &radic;P. A K5.6 head at 7 psi (the minimum) flows 14.8 gpm; at 28 psi it flows twice that, not four times.</p><p><b>Pipe friction (Hazen-Williams):</b> p = 4.52 Q<sup>1.85</sup> / (C<sup>1.85</sup> d<sup>4.87</sup>) psi per foot. Diameter is raised to almost the fifth power: one size up roughly thirds the loss.</p>
<table><tr><th>Pipe</th><th>C</th></tr><tr><td>All sprinkler pipe: wet, dry, preaction, interior, yard and underground</td><td>100 (company rule)</td></tr></table>
<p style="color:#7f93a3">Comparison only: the NFPA table value is 120 for wet steel. The company uses 100, and nitrogen earns no credit. This line has no effect on any calculation.</p>
<p><b>Pipe schedule</b> sets the inside diameter. One size cut decides it, regardless of main or branch: the cut size and smaller is threaded Schedule 40, every larger size is roll-grooved Schedule 10. The cut is a project setting, 2 in. by default (ASSUMED), and can be moved between 1&frac12; in. and 4 in. in the Sandbox. A 2 in. pipe is 2.067 in. inside as Schedule 40 and 2.157 in. as Schedule 10. 12 in. Schedule 10 (12.390 in. inside) is for above-ground headers only; underground and yard pipe is a different material and is not modelled.</p>
<p><b>The hydraulic calc checks hydraulics only.</b> Coverage belongs to plan review. If a room the system serves is not fully sprinklered, the calc result reads &ldquo;PASS (hydraulics only); coverage FAIL, see plan review&rdquo;.</p>
<p><b>Density / area method</b> (NFPA 13-2025 Ch. 19): every sprinkler in the hydraulically most remote area must deliver the design density.</p>
<table><tr><th>Hazard</th><th>Density</th><th>Area</th><th>Hose</th><th>Duration</th></tr><tr><td>Light</td><td>0.10</td><td>1,500</td><td>100</td><td>30</td></tr><tr><td>Ordinary 1</td><td>0.15</td><td>1,500</td><td>250</td><td>60&ndash;90</td></tr><tr><td>Ordinary 2</td><td>0.20</td><td>1,500</td><td>250</td><td>60&ndash;90</td></tr><tr><td>Extra 1</td><td>0.30</td><td>2,500</td><td>500</td><td>90&ndash;120</td></tr></table>
<p>The remote area is a rectangle 1.2&radic;A long, parallel to the branch lines. Dry and double-interlock systems add 30% to A.</p>
<p><b>What starves the far end:</b> long dead-end branch lines, small cross mains, feeding from one corner. <b>What fixes it:</b> feed from the middle, step pipe sizes up toward the riser, shorten the lines.</p>` },
  { id: 'sig', t: 'Detection and signals', h: `<p>NFPA 72 sorts everything into three kinds of signal. Knowing which is which is half of operating a site.</p>
<table><tr><th>Signal</th><th>Means</th><th>Examples</th></tr><tr><td style="color:#ff4b3a">ALARM</td><td>fire, now</td><td>waterflow, aspirating Fire 1 and Fire 2, spot smoke detection, manual station</td></tr><tr><td style="color:#ffb224">SUPERVISORY</td><td>the protection is impaired</td><td>valve tamper (2 turns or 1/5 travel), low or high air (per-valve setpoints), aspirating Alert and Action, pump running, pump power loss, low fuel, low tank, room below 40&nbsp;&deg;F, a Manual Release zone bypass in a contract</td></tr>
<tr><td style="color:#ffe45c">TROUBLE</td><td>the alarm system itself is impaired</td><td>panel AC failure, low battery, loss of communication with a dead panel (reported by the supervising station, after its supervision interval), loss of supply air (compressor or nitrogen source unavailable)</td></tr>
<tr><td style="color:#c59bff">OPEN</td><td>release input, class not elected</td><td>P latched on a preaction valve (PSL-REL or PA-REL)</td></tr></table>
<h4>SIGNAL CLASSES</h4><table><tr><th>Signal</th><th>Class</th><th>Setting</th></tr><tr><td>Aspirating Alert, Action</td><td>supervisory (pre-alarm)</td><td>supervisory or alarm. ASSUMED, NEEDS PE REVIEW</td></tr><tr><td>Latched P (release input)</td><td>OPEN: not elected</td><td>not elected, alarm or trouble. Supervisory is blocked. ASSUMED, NEEDS PE REVIEW</td></tr>
<tr><td>Fire 1, Fire 2, manual station, waterflow</td><td>alarm</td><td>fixed</td></tr><tr><td>Low air, high air, valve tamper</td><td>supervisory</td><td>fixed</td></tr><tr><td>Panel AC failure, low battery, loss of communication (dead panel)</td><td>trouble</td><td>fixed</td></tr><tr><td>Loss of supply air</td><td>trouble</td><td>fixed (PRACTICE). A compressor or nitrogen power or controller fault is equipment trouble, its own signal; the pressure drop it causes is still reported by the low-air supervisory</td></tr></table>
<p>A closed air supply valve is an impairment: tag it and restore it. It is not a supervisory signal here.</p>
<h4>SIGNAL SCHEDULE: WHO IS TOLD</h4><p><b>Alarm signals go to the fire department; supervisory and trouble signals go to the supervising station only</b> (PRACTICE). Alert and Action are pre-alarm: how they are handled is the owner&rsquo;s election, supervisory is the usual default, and they never call the fire department by themselves, even where they are elected alarm. A latched P on an electric / electric trim is OPEN and is not dispatched by itself either. Open the live table from the Site dialog or from a cause-and-effect matrix (<b>Signal schedule</b>): it is generated from the same registry the panel uses, so it follows the classes elected on the site. At the default classes:</p>${DI.MAN.sched}
<p>The annunciator lists alarm first, then OPEN items, then supervisory, then trouble. Its banner reads OPEN ITEM only when nothing else is present (ASSUMED presentation). Each class has its own sound: a bell for alarm, a two-tone chirp for an OPEN item, a short beep for supervisory, a low pulse for trouble (ASSUMED presentation). <b>Silence</b> on the panel acknowledges the signals: nothing is reset, nothing clears, and a new signal sounds again. A dead panel shows and sounds nothing; its line on the annunciator is the supervising station&rsquo;s.</p>
<p><b>Aspirating smoke detection</b> (VESDA and similar) draws air through sampling pipe to a laser chamber. It reports in stages:</p><ul><li><b>Alert</b>: pre-alarm. It never arms a release. Investigate: this is the stage where a person with a CO&#8322; extinguisher wins.</li><li><b>Action</b>: pre-alarm. Still no release.</li><li><b>Fire 1</b>: alarm, and the detection leg of the preaction release: D is true whenever the level is at or above Fire 1. Water still needs P.</li><li><b>Fire 2</b>: escalation only. It is never a release input by itself.</li></ul>
<p>A reading that jumps past several thresholds at once is logged stage by stage, in order, at the same time: Alert, Action, Fire 1, Fire 2. The detector reports its highest stage; the stages below it stay on the annunciator, struck through, as the record.</p>
<p>The four thresholds are a site setting, owner-set inside the listed range of the detector model: ASSUMED, NEEDS PE REVIEW. 0.03 / 0.06 / 0.12 / 1.2 %/ft are example values; the datasheets print setting ranges, not defaults. They must run Alert &lt; Action &lt; Fire 1 &lt; Fire 2, and <b>every</b> stage must sit inside its own listed range for the model chosen under Site. Listed ranges, %/ft obscuration ${DI.MAN.src}:</p>
${DI.MAN.asd}
<p>A value outside its range is never clamped: it stays as typed, shows red in the Site dialog and fails plan review. Changing the model never changes a threshold. The spot detector threshold is a site setting too: 1.3 %/ft inside an example window of 0.5 to 4.0 %/ft.</p>
<p><b>NFPA 76 applies by room</b> (FA Lead, Cycle 8). Only a <b>${DI.ROOMS.tel.name}</b> room can be an NFPA 76 space; a data hall never is. The site setting &ldquo;NFPA 76 adopted on this site&rdquo; is only <b>the default for telecom rooms</b>, and each telecom room can override it with &ldquo;NFPA 76 applies here&rdquo;. Which rooms count as NFPA 76 telecom is a judgment call: PRACTICE, NEEDS PE REVIEW. In the Sandbox a data hall can be changed to a telecom room and back on the room itself. The ceilings are checked in every NFPA 76 room that holds an aspirating detector, each finding names the room, and a site with no such room is told so (&ldquo;${DI.N76_NO_ROOM}&rdquo;). On a <b>VEA</b> detector, and only there, Fire 1 is read per room: the room&rsquo;s own pick, else the site pick, else the default, which is 0.5 %/ft in an NFPA 76 telecom room and 1.23 %/ft in every other room. So a hall and a telecom room on one site can read different Fire 1 numbers, and the site setting no longer pushes 0.5 onto the halls. A save from before this change with the site setting on loads with its 0.5 stored as the site pick where it was only a default, and says once: &ldquo;${DI.N76_MIGRATED}&rdquo;</p><p><b>The NFPA 76 ceilings</b> (NFPA 76-2024 &sect;8.5.3.1.2.5): two plain ceilings. Alert at 0.2 %/ft or less, and the alarm ceiling of 1.0 %/ft applied to <b>Fire 1</b>, the first alarm stage. Action stays pre-alarm and Fire 2 has no NFPA 76 limit (PRACTICE, NEEDS PE REVIEW). There is no real conflict with the detector listing: the listed Fire 1 maximum of both models (0.614 %/ft) is tighter, so the listing binds first and the 1.0 ceiling can never be the limit. The Site dialog and plan review say so in one note. Plan review fails an Alert above 0.2 or a Fire 1 above 1.0. <b>Check against NFPA 76</b> under Site reads the thresholds against the two ceilings and writes nothing.</p>
<p><b>Spot detectors</b> need far more smoke, so they answer later. In white space a spot detector raises the alarm only, and release needs aspirating detection. In a support room (electrical, UPS) one listed, compatible spot detector in alarm is the detection leg: any one detector in the zone, and D AND P is still the double interlock.</p><p>An unwired switch still clicks. Nobody hears it. In this game an unwired device shows as <i>local only</i> and the fire department is not called.</p>
<h4>WHEN THE SUPERVISING STATION KNOWS (NFPA 72)</h4>
<ul><li><b>Trouble at the panel:</b> within ${DI.TROUBLE_PANEL_S} seconds (&sect;10.15.1, the same in 2019, 2022 and 2025). The game shows panel troubles at once, which is inside that ceiling.</li>
<li><b>AC failure</b> is transmitted to the supervising station after a delay of 60 to 180 minutes (&sect;10.6.9.3), an owner / AHJ setting under Site, 60 by default. If power comes back inside the delay nothing is sent. Until it is sent the annunciator row says so.</li>
<li><b>Low battery:</b> the code requires the battery voltage to be monitored and a trouble on failure, and states no low-battery voltage (NOT FOUND in 2019, 2022 or 2025; &sect;10.6.9.1; &sect;10.6.10.6 is charger failure). The standby hours set capacity, not the trouble setpoint. The trouble here is ${DI.LOWBATT_NOTE}: on the game&rsquo;s straight-line voltage curve (${DI.BATT_V_END} V at the end of discharge, ${DI.BATT_V_FLOAT} V on float, both ASSUMED) that is 1/12 of the capacity left. It shows at the panel within ${DI.TROUBLE_PANEL_S} s and is transmitted at once (ASSUMED).</li>
<li><b>Charger failure</b> is a trouble at the panel and at the station [CODE] (&sect;10.6.10.6.1 to .2); the battery stops charging. <b>Battery disconnected</b> is modelled as a trouble too (PRACTICE, not code): with no battery the panel dies the moment AC is lost. Both are sandbox faults on the panel, and neither is an input of D or P.</li>
<li><b>A silenced trouble sounds again</b> by itself every 24 hours or less while it is still active (&sect;10.15.9.1; &sect;10.15.10.7 for a Ch. 26 premises unit). The game uses exactly 24 h (ASSUMED). A trouble that has cleared does not resound.</li>
<li><b>A dead panel</b> sends nothing, so the station learns of it only when its supervision of the path runs out. That depends on the path, a site setting:</li></ul>
${DI.MAN.paths}
<p>The DACT figure is its 6-hour test-signal interval (${DI.MAN.dact.test}): a missed test is a trouble [CODE], but the time for annunciating it is not in the text held, so the interval is used as the delay (ASSUMED). A DACT has two channels, and <b>the failure of either channel sends a trouble on the other channel within ${DI.DACT_CHAN_S / 60} minutes</b> [CODE] (${DI.MAN.dact.chan}): on the DACT path, fail a channel from the panel in the Sandbox and the trouble shows at the panel at once and reaches the station ${DI.DACT_CHAN_S / 60} minutes later. With one channel down nothing else is delayed: every signal goes on the surviving channel at once. Two-way radio paths are not modelled.</p>
<p><b>Both DACT channels down.</b> Nothing from that panel reaches the station, alarms included, and nothing is dispatched from it; no outside path is invented. The panel keeps working: display, annunciation, the notification rule, the hooks and the release are untouched. It tries each signal <b>${DI.DACT_TRIES} times, ${DI.DACT_ATTEMPT_S} s each</b> (the code allows 5 to 10 attempts of 90 s or less [CODE], ${DI.MAN.dact.tries}; the count of ${DI.DACT_TRIES} is ASSUMED; the 2022 and 2025 annex table gives ${DI.DACT_TOTAL_S} s for all attempts), then raises <b>DACT TRANSMISSION FAILED</b>, the failure indication at the premises. The station reports a missed test after the 6 hours.</p>
<p><b>When a channel is back.</b> Every signal that is <b>still active</b> is sent, with its <b>original event time</b>, one every ${DI.DACT_SEND_S} s (ASSUMED): fire alarm first, then supervisory, then trouble [CODE: &sect;10.7.2, &sect;10.7.7], then a class that is not elected (a latched P on an electric / electric trim: OPEN is not a 10.7 class, so it goes last and never dispatches; where it sits is PRACTICE / OWNER, NEEDS PE REVIEW). Then the <b>restorals</b>, in the same order, then the communications-failure trouble and its restoral.</p>
<p><b>Hold and send</b> is a site setting on the DACT path, <b>on by default</b>. The code is silent on holding a signal after the attempts are spent (not found in 2019, 2022 or 2025): it is manufacturer behaviour, PRACTICE, NEEDS PE REVIEW. It decides only what happens to a signal that <b>restored inside the outage</b>. <b>On:</b> it is sent late, and its restoral follows. An alarm sent late <b>still dispatches the fire department</b>: a fire alarm signal received by the station is retransmitted at once (NFPA 72 &sect;26.2.1.2 [CODE], the same section in 2019, 2022 and 2025), and verification (&sect;26.2.2) is not a late-signal or no-dispatch path [CODE, 2019, 2022 and 2025]. <b>Off: drops what has restored; a live signal is always re-sent.</b> A dropped signal was never sent, so it has no restoral. A restoral for a signal the station already holds is never dropped, or the station would show an alarm that is over (PRACTICE, NEEDS PE REVIEW).</p>
<p><b>Restorals.</b> When a signal the station has is no longer a condition at the panel, the panel reports the restoral (NFPA 72 &sect;26.2.5.1 [CODE], VERIFIED in 2019, 2022 and 2025: the 2019 text is held and matches the later editions for this duty). With the path up it is one log line, &ldquo;RESTORAL to station&rdquo;. A fire alarm restores when the panel is reset or the device is restored by hand, so its restoral follows that. A restoral dispatches nothing. &sect;26.2.1.4 (subsequent signals) is in the 2022 and 2025 editions only; it is not modelled in any edition and is not shown on a 2019 site. On the hidden Canadian row: ${DI.CA_STATION_NOTE}</p>
<p><b>Waterflow latches until the panel is reset.</b> Latching a waterflow alarm until reset is <b>PRACTICE with code support, NEEDS PE REVIEW</b>. The label, by edition: &ldquo;${DI.REF72[2025].latch.replace(/§/g, '&sect;')}&rdquo; (2022: the same sections; 2019: &sect;10.18.1.1.2 in place of &sect;10.18.1.2). &sect;10.11.6 says resetting of alarm signals shall comply with &sect;23.8.2.2: the same number and sentence in 2019, 2022 and 2025 [CODE]. &sect;10.18.1.2 (2019: &sect;10.18.1.1.2) has the same words in every edition [CODE]. &sect;23.8.2.2 is about combined subsystems that share equipment; its wording differs by edition (2019 &ldquo;share control equipment&rdquo;, 2022 &ldquo;share equipment&rdquo;, 2025 a lead-in and a list), and it is <b>indirect support</b>: it stays in the cite list and is never quoted as a rule that alarms hold until reset. No NFPA 72 sentence says fire alarms latch until manual reset, and &sect;10.14.2 covers supervisory latching only. Detectors, manual stations and the release latches already held until reset; waterflow now does too: when the flow stops the alarm stays at the panel, marked &ldquo;latched: reset the panel&rdquo;. A reset with water still flowing says &ldquo;still in alarm&rdquo;; after the flow has stopped it clears. A dead panel holds no latch. A flow raised while the system is on test does not latch (SIMPLIFICATION). The switch itself, the inspector&rsquo;s test and the local gong are unchanged, and a latched alarm whose flow is over starts no new dispatch.</p>
<p><b>The hazard case.</b> One path still loses a live alarm: the panel dying with the signal queued. The queue shows it as <b>${DI.DACT_HAZARD_LABEL}</b>. ${DI.DACT_HAZARD.replace(/§/g, '&sect;')} (2019: &sect;26.6.4.1.5(6) and &sect;26.6.4.2.2(H).) The 6 h test itself is not modelled: it is text only.</p>
<p>The annunciator shows the live state in the <b>Supervising station queue</b>: RETRYING 3 of ${DI.DACT_TRIES}, then HELD, COMM FAILURE, then SENT hh:mm (late), with RESTORAL hh:mm once its restoral has gone; NOT SENT (hold off) for a signal that had restored; ${DI.DACT_HAZARD_LABEL} for the hazard case. The cause-and-effect matrix stays design intent and says so in a footnote.</p>
<h4>BATTERY AND STANDBY (NFPA 72 &sect;10.6.7.2, where adopted; AHJ to confirm)</h4>
<p>The battery must carry the panel through the standby hours and then the alarm time: <b>required Ah = (standby A &times; hours + alarm A &times; alarm minutes &divide; 60) &times; a sizing factor</b>. The factor follows the <b>NFPA 72 edition</b>, never the NFPA 13 edition: &times;1.20 in 2019 (&sect;10.6.7.2.1.1), &times;1.25 in 2022 and 2025 (&sect;10.6.7.2.14). With the ASSUMED loads (${DI.PANEL_LOADS.iStby} A standby, ${DI.PANEL_LOADS.iAlarm} A alarm) the default basis needs 15.2 Ah in 2025 and 14.6 Ah in 2019, so the default ${DI.PANEL_LOADS.ah} Ah battery passes. Pick the battery on the panel (${DI.BATT_AH.join(' / ')} Ah, ASSUMED picks). Plan review <b>fails</b> a battery below the requirement and warns <b>THIN</b> under a ${DI.STBY_THIN * 100} % margin (PRACTICE, NEEDS PE REVIEW).</p>
${DI.MAN.stby}
<p><b>Charger.</b> The charger must restore the battery within ${DI.RECHARGE_H} h after one full discharge (&sect;10.6.10.3.2, identical in 2019, 2022 and 2025) [CODE]. The window is ${DI.RECHARGE_H} h <b>for every battery size</b>: a bigger battery needs a bigger charger, the ${DI.RECHARGE_H} h never stretches. The battery pick stays free. The charger is picked on the panel in amperes (${DI.CHG_A.filter(Boolean).join(' / ')} A, or &ldquo;matched to the battery&rdquo;, the default): these are listing values, ASSUMED, because no charger ampere rating is in &sect;10.6.10 in any edition. A charger restores amperes &times; ${DI.RECHARGE_H} h of battery (ASSUMED: no taper, no efficiency loss), so 1 A restores 48 Ah. Plan review <b>fails</b> a battery larger than its charger can restore in ${DI.RECHARGE_H} h; an undersized charger also recharges more slowly in the game, and a larger one never charges faster than the ${DI.RECHARGE_H} h rate. Battery and charger cost are ASSUMED and no goal reads them.</p>
<p>The <b>standby basis</b> is a site setting with three choices, all for a releasing panel. The FM row (90 h + 10 min, FM DS 5-40 &sect;2.3.4, September 2007 edition, may not be current) needs 56.7 Ah, so the default battery fails it until a 65 Ah pick: that is why FM is an election of its own and never automatic with the insurer setting. The building FACU, EVACS and ESS rows are reference only: the game has no such panel. <b>Generator-backed</b> (2025 only, &sect;10.6.7.3.1(2); optional, default battery only): batteries for ${DI.GEN_BATT_H} h and the generator covers 24 h; under 2019 and 2022 the setting is ignored. <b>Recharge</b>: the charger restores a full discharge within ${DI.RECHARGE_H} h (&sect;10.6.10.3.2) [CODE]. 2022 and 2025 require listed or component-recognized rechargeable batteries (&sect;10.6.10.1.3; 2019 has no such rule). The rule about restoring a failed charger before half the battery is used is for supervising-station equipment only and is not modelled.</p>
<p><b>The NFPA 72 edition is its own site setting</b>, separate from NFPA 13: adoption is by the AHJ and the two can differ (PRACTICE). Auto, the default, follows the NFPA 13 edition. The multiple-path figure for 2025 is ASSUMED: 2025 &sect;26.6.3.4(1) is a 6 h supervision interval, not a failure-annunciation time, and no annunciation time was found in the 2025 text.</p>
${DI.MAN.nac}` },
  { id: 'ce', t: 'Cause and effect', h: `<p>A cause-and-effect matrix says, for every input on a zone, what the fire alarm system does about it. Open it from a preaction valve (<b>Cause and effect matrix</b>) or from the releasing panel, which offers one per wired zone. It is read-only, and it is <b>generated</b>, not written: the signal classes come from the registry the alarm code itself reads, and the solenoid column from the release formula on that zone&rsquo;s trim and bypass setting. The tests hold every row against the fire alarm lead&rsquo;s truth table and against the running engine.</p>
<table><tr><th>Column</th><th>Says</th><th>Basis</th></tr>
<tr><td>Input, Tag</td><td>the input the row stands for, and where its rule comes from</td><td>see the tags below</td></tr>
<tr><td>SignalClass</td><td>alarm, supervisory, trouble, or pre-alarm (Alert and Action)</td><td>[CODE] for the three classes; [OWNER] for how pre-alarm is handled</td></tr>
<tr><td>PanelAnnunciation</td><td>zone-identified display and audible at the panel; a dead panel displays nothing</td><td>[CODE]</td></tr>
<tr><td>SS_Transmit</td><td>what the supervising station receives, when, and whether the fire department is dispatched (see &ldquo;Signal schedule&rdquo; and &ldquo;When the supervising station knows&rdquo; under Detection and signals)</td><td>[CODE] for alarm, supervisory and trouble; [OWNER] for pre-alarm; station-only for supervisory and trouble is [PRACTICE]</td></tr>
<tr><td>LocalNAC</td><td>alarm only. Supervisory and trouble never sound the notification appliances</td><td>[CODE]. Here it is a rule read from the class: notification circuits are not modelled</td></tr>
<tr><td>Solenoid</td><td>electric / electric: energized only when D AND P. Electric / pneumatic: energized on D, and water also needs P at the actuator</td><td>[PRACTICE]</td></tr>
<tr><td>HVAC_Hook</td><td>an output contact for HVAC shutdown or a damper, where elected. The setting is the trigger stage: Fire 1, Fire 2 or waterflow</td><td>[OWNER], NEEDS PE REVIEW. Default none. Never Alert or Action</td></tr>
<tr><td>EPO_Hook</td><td>an output contact for power isolation, where elected: on the waterflow row only</td><td>[OWNER], NEEDS PE REVIEW (an NEC 645 / FM DS 5-32 election). Default OFF, never automatic</td></tr></table>
<p><b>Tags:</b> ${DI.CE_LEGEND.join('; ')}.</p>
${DI.MAN.ceRows}
<ul><li><b>P is OPEN, never supervisory.</b> A latched P is a release input whose class the engineer has not elected. It shows OPEN until it is elected alarm or trouble under Site. Supervisory is blocked for it, on both trims.</li>
<li><b>Hooks are hooks only, never automatic.</b> Electing one under Site puts an output contact in the matrix for others to wire. The game shuts down no fan, no damper and no power, and nothing in the plant changes.</li>
<li><b>HVAC trigger</b> (OWNER, NEEDS PE REVIEW): none by default, or Fire 1, Fire 2 or waterflow. It is never Alert or Action, even where they are elected alarm. With Fire 1 elected, Fire 2, the manual station and waterflow trip it too, so the release rows show it (PRACTICE). With Fire 2 elected it trips on <b>every row where Fire 2 = 1</b>, whether or not that row released; a release alone (Fire 1 and P, or the Manual Release zone) does not trip it. With waterflow elected it trips on waterflow only. A tripped cell names the input that tripped it. Duct-detector shutdown (IMC) is a separate device, outside this matrix.</li>
<li><b>EPO is on waterflow, not on the release command</b> (PRACTICE). Waterflow proves water is in the system, and on an electric / pneumatic trim it is the only way the panel knows the valve opened. So the hook sits on the waterflow row only and never on a release or valve-open row. OFF by default.</li>
<li><b>Greyed rows</b> are paths that exist but not on this site: the Manual Release zone with the 9(c) bypass OFF or on an electric / pneumatic trim, the DETECTION station with the bypass ON, the tamper row with no control valve, the DACT channel row on a path that is not a DACT.</li>
<li><b>ACTIVE NOW</b> marks the rows whose signal is present on the zone, and follows the plant while the dialog is open.</li>
<li><b>Low and high air</b> are supervisory and never a release input. <b>Loss of supply air</b> is trouble: equipment trouble, its own signal (PRACTICE).</li></ul>
<p style="color:#7f93a3">${DI.CE_EXCLUDED} The matrix is design intent. Its last footnote, word for word: &ldquo;${DI.CE_DACT_NOTE}&rdquo;</p>
<p><b>Manual pull and manual release</b> are dispatched the same way: both are alarm signals to the station and the fire department (PRACTICE). The point label differs, &ldquo;MANUAL PULL, ZONE x&rdquo; for a station typed DETECTION and &ldquo;MANUAL RELEASE, ZONE x&rdquo; for the Manual Release zone, and so does the logic: the pull joins D and still needs P; the Manual Release zone goes straight to release (9(c), OFF by default, NEEDS PE REVIEW).</p>` },
  { id: 'itm', t: 'Testing and maintenance', h: `<p>NFPA 13 says how to build it. NFPA 25 says how to keep it working. The numbers you will use most:</p>
<table><tr><th>Item</th><th>Frequency</th></tr><tr><td>Control valves (supervised)</td><td>inspect monthly; full operation annually</td></tr><tr><td>Dry / preaction air and water gauges</td><td>weekly, or monthly if supervised</td></tr><tr><td>Main drain test</td><td>annually; quarterly behind a backflow preventer on a sole supply</td></tr>
<tr><td>Waterflow alarm devices</td><td>semi-annually (vane and pressure switch)</td></tr><tr><td>Dry valve partial trip</td><td>annually</td></tr><tr><td>Dry valve full-flow trip</td><td>every 3 years</td></tr><tr><td>Dry system air leakage</td><td>every 3 years</td></tr><tr><td>Preaction valve trip</td><td>annually</td></tr>
<tr><td>Low-point drains</td><td>before and during freezing weather</td></tr><tr><td>Fire pump churn run</td><td>weekly (diesel 30 min, electric 10 min)</td></tr><tr><td>Fire pump flow test</td><td>annually</td></tr><tr><td>Internal pipe assessment</td><td>every 5 years</td></tr></table>
<h4>AFTER A TRIP OR A BROKEN HEAD: PUTTING IT BACK</h4><p>One sequence of thirteen steps, in the physical order. It is generic practice (NFPA 25 and maker IOMs); the valve maker&rsquo;s IOM governs the specifics: the reset procedure, the trim reset, how slowly to open the control valve. A step that does not apply counts as done.</p>${DI.MAN.rec}
<p><b>Two panel resets, for two reasons.</b> Reset #1 clears detection so the clapper can be reset. Reset #2 comes after the air is back and clears the pressure-loss (P) latch and the troubles. A reset while the pipe is still below P trip latches P again and scores nothing. <b>Silence is not reset: it acknowledges the sound and clears nothing.</b></p>
<p><b>Scored once, practised everywhere.</b> Only the broken-sprinkler incident in the contract 5 drill is scored: 13 of 13 in order earns the star. The <b>recovery rating</b> reads <b>water stopped</b>, the time from the alarm to the control valve closed, plus every step in order: ${DI.RECOVERY_TIERS[0].s} s or less is three stars, ${DI.RECOVERY_TIERS[1].s} s or less is two, and any complete in-order recovery is one (ASSUMED, play test; informational, not a pass or fail, and separate from the contract&rsquo;s stars). ${DI.RECOVERY_TIP} When water was stopped in under ${DI.RISER_NOTE_S} s the report adds, on its own line: &ldquo;${DI.RISER_NOTE}&rdquo; The report keeps the times apart: &ldquo;Operator steps took: 23 s&rdquo; is the recovery itself, and &ldquo;Main drain test took: 34 s&rdquo; is step 14 on its own line. It keeps the water apart too, and never adds it up: &ldquo;Discharged through the open head: 121 gal&rdquo; and &ldquo;Main drain test: 156 gal (to drain, not to the floor)&rdquo;. Water out of a system drain, an inspector&rsquo;s test or the pump test header is neither: when there is some it gets its own line: &ldquo;Other drains and test connections (system drain, inspector&rsquo;s test): 5 gal, to drain, not to the floor.&rdquo; The <b>air refill is two numbers on two labeled lines</b> (FP Lead and Fire Tutor, Cycle 8), and only the first is ever compared with the limit. The code check is on top, because it decides pass or fail: &ldquo;Code check: largest zone alone, from 0 psig: 19.1 min. Limit 30 min (NFPA 13). Passes.&rdquo; with the section of the edition in force (2019 and 2022 &sect;8.2.6.3.2; 2025 &sect;8.2.7.3); where the compressor is too small it ends &ldquo;Fails: the compressor is too small for this zone. Size it to refill the largest zone to normal pressure in 30 min.&rdquo; (the failure itself is the plan review finding). Under it is what the drill measured: &ldquo;Air refill this drill, measured: 12.2 min (zones refilled at the same time, from partly full). Informational.&rdquo; That line never carries a limit or a verdict: recovery time is mostly compressor time, and waiting for it is not punished. Whenever zones share a compressor the report adds: &ldquo;Note: 3 zones share this compressor. It is sized for the largest zone, not for all zones at once.&rdquo; Where an owner / insurer refill target is set, one more line says whether the largest zone alone meets it. The total is beside them. Every other recovery, after a trip test or in the Sandbox, is practice: the valve shows a <b>Recovery checklist (PRACTICE)</b> with each step done, pending or not applicable, and nothing gates on it.</p>
<p><b>Reopening too early, in practice.</b> Outside the scored drill incident the control valve opens with a warning that lists what is still open. If a head is still open and the valve is still tripped or P is latched, water goes out through that head, and the log then says why: in a data hall that is water on the IT load. The scored drill incident keeps its hard stop instead.</p>
<p><b>Main drain test after the reopen.</b> ${DI.MDT_LINE} In the contract 5 drill this is <b>step 14</b> of the scored recovery: it counts when it is run after the control valve is back open and both readings are recorded. Its label in the drill checklist is the Tutor&rsquo;s: &ldquo;${DI.RECOVERY_DRAIN[1]}&rdquo; A drop of more than 10 percent against the last test does not fail the step and is not an automatic failure: it is a trigger to investigate. The result reads <b>INVESTIGATE</b>, cites the rule (&ldquo;${DI.REF25.passLine.replace(/§/g, '&sect;')}&rdquo;, VERIFIED) and says: &ldquo;${DI.mdtHint(0.12)}&rdquo; <b>Check the valves upstream</b> on the valve reports every control valve on the supply path and logs the check. In a drill, a drop over 10 percent that is not followed by that check, a control valve on the supply path reopened, or a later passing test is one informational error line, &ldquo;${DI.MDT_NOT_INVESTIGATED}&rdquo; (PRACTICE scoring). With no earlier test the reading is recorded as the baseline and nothing is scored. If the test is skipped after the valve was reopened the report says: &ldquo;${DI.MDT_SKIPPED}&rdquo; There is no timed nag. In practice it is a tip. What the code requires after a control valve is closed and reopened is the <b>valve status test</b> (NFPA 25-2023 and 2026 &sect;13.3.3.4, VERIFIED; 2020 has the table row only); the main drain test is its own line item, annual (2023 &sect;13.2.2, 2020 &sect;13.2.3, VERIFIED), and running it at this point is company practice. Static first, then full flow, close slowly, confirm static recovers, compare with the previous test: ASSUMED teaching practice.</p>
<p>Until the control valve is open again the building is unprotected. That time is the impairment, and it should be short.</p>` },
  { id: 'dc', t: 'Data center notes', h: `<ul><li><b>Data halls and electrical rooms:</b> double-interlock preaction is the usual owner and insurer position (FM Global Data Sheet 5-32), with aspirating detection. Hazard is commonly taken as Ordinary Hazard Group 1 or 2 depending on the owner standard.</li>
<li><b>Hot / cold aisle containment</b> is an obstruction. Either sprinklers go inside it, or the containment is arranged to drop away or not obstruct (NFPA 75 / 76). The 2025 edition of NFPA 13 adds requirements for <i>supplemental</i> sprinklers below obstructions.</li>
<li><b>System count:</b> a hyperscale hall is far larger than one 500-gal preaction system. Halls are zoned into several valves, each with its own detection zone. Count the zone volume, not the pipe alone: fittings and trim tip a 498 gal layout over 500 gal, and then it has to pass the 60 s timed test or be rezoned. Where FM insures the site the limit is 30 s at any volume (FM DS 5-32, NEEDS PE REVIEW), so a zone can pass NFPA 13 and fail FM.</li><li><b>Battery rooms</b> (lithium-ion): NFPA 855 drives higher densities and often dedicated systems; treat this game&rsquo;s OH2 as a placeholder.</li>
<li><b>Loading docks, generator enclosures, exterior canopies:</b> dry pipe.</li><li><b>Water supply:</b> rural sites mean tanks and redundant pumps (commonly one electric and one diesel, or N+1 diesel), on a looped yard main with sectional valves so one break does not isolate a building.</li>
<li><b>Nitrogen</b> is standard on preaction and dry systems at this scale.</li></ul>` },
  { id: 'site', t: 'Site settings and company rules', h: `<p>The <b>Site</b> button holds the settings that belong to the project, not to one valve. In a contract they are read-only: the basis of design is fixed by the AHJ, the owner and the insurer. They can be changed in the Sandbox. Two labels are used everywhere in the game:</p>
<ul><li><b>ASSUMED</b>: a value the company has not fixed. It is a tunable default, not a rule.</li><li><b>NEEDS PE REVIEW</b>: a choice an engineer of record has to make.</li></ul>
<h4>COMPANY RULES (LOCKED)</h4><ul><li>Wet, dry and double-interlock preaction systems only.</li><li>Preaction release = (D AND P) OR (bypass 9(c) AND Manual Release zone), where D = Fire 1 detection OR a manual station typed DETECTION. The second path is electric / electric only, OFF by default, NEEDS PE REVIEW. Low air is supervisory only and never a release input.</li><li>Only Fire 1 releases. Alert never arms. Fire 2 never releases by itself.</li>
<li>Panel failure never releases water.</li><li>Hazen-Williams C = 100 for all pipe. No nitrogen credit.</li><li>The release truth table is the fire alarm lead&rsquo;s file, copied byte for byte and pinned by its hash. It is never edited in the game&rsquo;s repository.</li></ul>
<h4>ENFORCED EDITION</h4><p>NFPA 13-2019, 2022 or 2025 for US sites, default 2025. Plan review and the trip-test report cite the chosen edition, and plan review shows the delta from 2025 on its first line. Pass and fail do not differ by edition in this version.</p>
<p><b>NFPA 72 has its own edition setting</b>: Auto (follows NFPA 13, the default), 2019, 2022 or 2025. Adoption is by the AHJ and can differ from NFPA 13 (PRACTICE). It changes the fire alarm citations only: supervising station, panel power, DACT.</p>
<h4>INSURER</h4><p>None by default. With FM, dry and double-interlock systems must deliver water in 30 s at any volume, and the most stringent limit governs. Every contract is winnable with the default.</p>
<h4>ASSUMED VALUES</h4><table><tr><th>Item</th><th>Default</th></tr><tr><td>Preaction setpoints (per valve, from the maker trim)</td><td>high 50, normal 40, low 30, P trip 20 psi</td></tr><tr><td>Minimum margin, low air above P trip</td><td>5 psi</td></tr>
<tr><td>Pipe size cut (largest size on threaded Schedule 40)</td><td>2 in.; larger sizes Schedule 10; same cost per size</td></tr><tr><td>Zone volume: fittings allowance, trim volume</td><td>5 % of pipe volume, 2 gal per valve</td></tr><tr><td>Aspirating thresholds (owner-set example values inside the model&rsquo;s listed range; also NEEDS PE REVIEW)</td><td>0.03 / 0.06 / 0.12 / 1.2 %/ft</td></tr>
<tr><td>Spot detector alarm threshold (example value) and window</td><td>1.3 %/ft inside 0.5 to 4.0 %/ft</td></tr>
<tr><td>Signal class of Alert and Action</td><td>supervisory</td></tr><tr><td>Signal class of a latched P; banner priority of an OPEN item</td><td>not elected (OPEN); shown only when nothing else is present</td></tr>
<tr><td>Releasing panel standby basis (site setting; the default is the building-FACU rule used for a releasing panel, PRACTICE)</td><td>${DI.PANEL_STANDBY_H} h + 5 min</td></tr><tr><td>Panel loads for the standby calculation (listing values) and the default battery; battery picks</td><td>${DI.PANEL_LOADS.iStby} A standby, ${DI.PANEL_LOADS.iAlarm} A alarm, ${DI.PANEL_LOADS.ah} Ah; ${DI.BATT_AH.join(' / ')} Ah</td></tr>
<tr><td>Panel LOW BATTERY trouble: the listed low-voltage setpoint (OWNER/listing; also NEEDS PE REVIEW); the voltage curve</td><td>${DI.LOWBATT_V} V on a 24 V system; a straight line from ${DI.BATT_V_END} V (end of discharge) to ${DI.BATT_V_FLOAT} V (float); transmitted at once</td></tr>
<tr><td>DACT: number of transmission attempts (the 5 to 10 bound and the 90 s are CODE); seconds between two sends when a channel is back</td><td>${DI.DACT_TRIES} attempts; ${DI.DACT_SEND_S} s</td></tr><tr><td>Silenced trouble resounds (the code says 24 h or less)</td><td>exactly 24 h</td></tr>
<tr><td>AVC bypass open, compressor not modeled (no cut-out, no rated max discharge): where the zone drifts</td><td>${DI.AVC_BYPASS_PSI} psi (ASSUMED)</td></tr><tr><td>Compressor rated max discharge and relief setpoint, the ceiling of an open AVC bypass (the lower of the two); on a real job the values come from the selected unit</td><td>not modeled / none; choices ${DI.COMP_MAXPSI.filter(Boolean).join(' / ')} psi and ${DI.COMP_RELIEF.filter(Boolean).join(' / ')} psi</td></tr>
<tr><td>Charger amperes, restorable Ah, and the battery and charger cost (no charger ampere rating is in NFPA 72 &sect;10.6.10)</td><td>matched to the battery; choices ${DI.CHG_A.filter(Boolean).join(' / ')} A; amperes &times; ${DI.RECHARGE_H} h, no taper; $${DI.BATT_COST_PER_AH} per Ah</td></tr>
<tr><td>Refrigerated Space room: contents value per tile</td><td>$${DI.ROOMS.cold.val.toLocaleString('en-US')}</td></tr><tr><td>Sub-step while a return-step system drain is letting air out</td><td>${DI.RET_SUBSTEP} s</td></tr><tr><td>Wording of the low-air text of the return to normal for an episode with no drain open (the Tutor gave every other text), and of the last sentence of the step 14 banner</td><td>written in the same form</td></tr><tr><td>NAC check: appliance minimum voltage; start voltage when none is given; THIN margin (company rule, PRACTICE)</td><td>${DI.NAC_VMIN} V; ${DI.NAC_V_END} V; ${DI.NAC_THIN * 100} %</td></tr><tr><td>NAC check: appliance current at the minimum voltage, per candela (round numbers, not from a listing)</td><td>${DI.NAC_CDS.map((c) => DI.NAC_CD[c].toFixed(2) + ' A at ' + c + ' cd').join(' / ')}</td></tr><tr><td>NAC check: start voltage picks; most appliances on the circuit</td><td>${DI.NAC_VSTART.filter(Boolean).map((v) => v.toFixed(1)).join(' / ')} V; ${DI.NAC_N_MAX}</td></tr><tr><td>Owner / insurer refill target picks, and judging it on the largest zone alone from 0 psig</td><td>none; ${DI.OWNER_REFILL.filter(Boolean).join(' / ')} min</td></tr><tr><td>Telecom / MMR room: contents value per tile</td><td>$${DI.ROOMS.tel.val.toLocaleString('en-US')}</td></tr><tr><td>Reading &ldquo;AVC high&rdquo; in the relief warning as the high-air setpoint of a zone the compressor feeds</td><td>high air</td></tr>
<tr><td>Supervising station on a DACT: time before a missed test (a dead panel, or both channels down) is annunciated; not in the text held</td><td>6 h, its test-signal interval</td></tr><tr><td>Supervising station on multiple paths, NFPA 72-2025 (no failure-annunciation time found in 2025)</td><td>6 h, as in 2019 and 2022</td></tr>
<tr><td>Compressor sizing margin on the 30-minute minimum (also NEEDS PE REVIEW; not an NFPA factor)</td><td>&times;${DI.AIR_SIZING.margin}</td></tr><tr><td>Compressor cut-out pressure (a sizing input only on a compressor direct to the system; with an AVC regulating the zone is sized at normal)</td><td>none; choices ${DI.COMP_CUTOUT.filter(Boolean).join(' / ')} psi</td></tr>
<tr><td>Return to normal after the air test: a Finish press that is refused</td><td>one error for each new set of blockers (PRACTICE); a set that only shrank adds none (that reading is ASSUMED)</td></tr>
<tr><td>Signals outside the FA Lead&rsquo;s schedule (spot detector, pumps, tank, low temperature, loss of communication, DACT channel, impairment; the DACT transmission failure, charger failure and battery disconnected carry the Lead&rsquo;s Cycle 6 tags)</td><td>their classes as shown in the signal schedule; station only except the spot detector</td></tr>
<tr><td>Electric / electric P latch with the panel dead</td><td>lost with panel power, read again on restore</td></tr><tr><td>&ldquo;About 0 psi&rdquo; before a head is replaced (the gate itself is confirmed; the value is ASSUMED)</td><td>${DI.SAFE_PSI} psi</td></tr>
<tr><td>24 h air test: start tolerance, time allowed to charge to test pressure</td><td>${DI.AIR_TEST.tol} psi, ${DI.AIR_TEST.chargeMax / 60} min</td></tr><tr><td>Operator log size</td><td>${DI.ACTS_MAX} entries</td></tr><tr><td>Sound cue per signal class</td><td>bell, chirp, beep, pulse</td></tr>
<tr><td>Contract 5 recovery rating, on &ldquo;water stopped&rdquo; (the alarm to the control valve closed) plus every step in order; to be tuned in play test. Operator-step time and the air refill are reported beside it; informational, separate from contract stars</td><td>3 stars at ${DI.RECOVERY_TIERS[0].s} s or less, 2 at ${DI.RECOVERY_TIERS[1].s} s or less, 1 for any complete in-order recovery</td></tr></table>
<h4>ASPIRATING DETECTOR MODELS: LISTED RANGES</h4><p>Each listing bounds every threshold per stage, per model. The ranges are read from the maker&rsquo;s own datasheets ${DI.MAN.src}: the UL Product iQ listing itself could not be read. The default model is VESDA-E VEP.</p>${DI.MAN.asd}
<p><b>VESDA-E VEA is a Fire 1-only model</b> (Cycle 7). It has one stage: pick 0.5 (High), 1.23 (Enhanced) or 2.5 (Standard) %/ft in the Site dialog; anything else fails plan review. Its Alert, Action and Fire 2 are ${DI.VEA_NA}: they do not exist in the game for this model, so the Fire 2 HVAC hook and those matrix rows read &ldquo;not available&rdquo;. Default 0.5 in a telecom room where NFPA 76 applies, 1.23 in every other room, whatever the site setting; a room can carry its own pick, on this model only (which rooms count as NFPA 76 telecom: PRACTICE, NEEDS PE REVIEW). ${DI.ASD_MODELS.VEA.oemNote} ${DI.ASD_RECORDED.VEA.note}</p><p><b>NFPA 76.</b> The 1.0 %/ft alarm figure is VERIFIED: NFPA 76-2024 &sect;8.5.3.1.2.5, Alarm condition, air-sampling, &ldquo;3.2 percent per meter (1.0 percent per foot) obscuration (effective sensitivity at each port)&rdquo;; the same figure is in NFPA 76-2020. Applying that Alarm condition to Fire 1, on a VEA detector too, is PRACTICE, NEEDS PE REVIEW: 0.5 meets the ceiling, 1.23 and 2.5 are above it.</p><p>Not offered: FAAST LT-200 and FLEX (no UL 268 or FM listing on the sheets), TITANUS and FAAST XM / XS (conflicting or non-current sheets).</p>
<h4>NEEDS PE REVIEW</h4><ul><li>Manual Release zone that bypasses P (OFF by default; owner/insurer exception; shown as an impairment in a contract).</li><li>Signal classes: Alert and Action (supervisory by default), and a latched P (class not elected; supervisory blocked). Loss of supply air is settled: trouble (PRACTICE).</li><li>Aspirating default thresholds (0.03 / 0.06 / 0.12 / 1.2 %/ft): owner-set inside the model range. The datasheets print no defaults.</li><li>NFPA 76 ceilings: Alert 0.2 %/ft, and the 1.0 %/ft alarm ceiling (the figure is VERIFIED) applied to Fire 1, with Action as pre-alarm (PRACTICE); mapping the NFPA 76 Alarm condition to VEA Fire 1, and which rooms count as NFPA 76 telecom (a room type, with the site setting as the default).</li><li>HVAC and EPO hooks: the owner&rsquo;s election, the trigger stage, and the NEC 645 / FM DS 5-32 interface.</li><li>DACT hold and send after a communications failure (no code basis; a setting, on by default) and &ldquo;a live signal is always re-sent&rdquo;; the count of ${DI.DACT_TRIES} attempts; where OPEN sits in the restore order (last here; the alternative is to leave it out of the queue); never dropping a restoral under hold OFF.</li><li>Latching a waterflow alarm until a panel reset (PRACTICE with code support: &sect;10.11.6, &sect;23.8.2.2 indirect, &sect;10.18.1.2).</li><li>The NAC check: the ${DI.NAC_VMIN} V appliance minimum, the ASSUMED ${DI.NAC_V_END} V end-of-discharge start, the ASSUMED listing currents per candela, the ${DI.NAC_THIN * 100} percent THIN margin (company rule), the method on 2019 and 2022 sites (PRACTICE) and the 2023 Table 8 ohms on a NEC 2026 site.</li><li>The owner / insurer refill target method (the largest zone alone) and the two compressor relief warnings (PRACTICE).</li><li>Step 14, the main drain test after a reopen, as company practice.</li><li>The optional tamper switch on the AVC bypass (no code requirement verified).</li><li>The 60-minute refill limit read per zone as &ldquo;every room is a freezer held below 5 F&rdquo;.</li><li>Sequential, largest-first refill as an owner practice.</li><li>Scoring the main drain 10 percent drop (the cite is VERIFIED, the scoring is PRACTICE).</li><li>Standby battery: FM 90 h + 10 min (FM DS 5-40, 2007 edition); the 10 min owner row; the generator-backed 4 h case; the THIN screen under ${DI.STBY_THIN * 100} %.</li><li>A compressor cut-out above the high-air supervisory as a plan review fail where there is no AVC.</li><li>24 h air test pressure at the greater of 40 psi or the zone&rsquo;s normal pressure (company practice).</li><li>The &times;${DI.AIR_SIZING.margin} compressor sizing margin and the ideal-gas sizing screen.</li><li>The margin above the P release set point on the return-to-normal step (${DI.P_MARGIN} psi, ASSUMED).</li><li>Low-battery setpoint: the listed manufacturer voltage setpoint (OWNER/listing).</li><li>AC-fail transmission delay, 60 to 180 minutes (OWNER / AHJ), and the supervising-station path type (OWNER).</li><li>FM 30 s water delivery at any volume for dry and double interlock (FM DS 5-32), applied only when the insurer setting is FM.</li><li>Lithium-ion / ESS room density and approach. The battery room here is a placeholder.</li></ul>
<h4>VERIFY BEFORE USE</h4><p>Verified so far: the 24 h air test section in every edition (2019 &sect;28.2.2.1; 2022 and 2025 &sect;29.2.2.1); the 30-minute refill (2019 and 2022 &sect;8.2.6.3.2; 2025 &sect;8.2.7.3; N&#8322;-only 2019 and 2022 &sect;8.2.6.8.4; 2025 has no N&#8322;-only clause, &sect;8.2.7.6 has none) and the 60-minute allowance for refrigerated spaces below 5&nbsp;&deg;F (2019 and 2022 &sect;8.2.6.3.3 and &sect;8.2.6.8.5; 2025 &sect;8.2.7.4); the NFPA 76 alarm figure of 1.0 %/ft (NFPA 76-2024 &sect;8.5.3.1.2.5; the same in 2020); NFPA 72-2019, 2022 and 2025 &sect;26.2.1.2 (a received fire alarm is retransmitted at once), &sect;26.2.2 (verification) and &sect;26.2.5.1 (restorals are reported); NFPA 72 &sect;10.11.6 and &sect;10.18.1.2 (2019: &sect;10.18.1.1.2) on resetting alarm signals, and &sect;7.2.1(8) (NAC voltage-drop calculations are a documentation item), in all three editions; NFPA 72-2025 &sect;18.3.7.1 to &sect;18.3.7.6 (the NAC voltage-drop method) and NFPA 70-2023 Chapter 9 Table 8; the 1.5 psi air-test pass line as an absolute value; the AVC as a device of its own (2019 &sect;8.2.6.6.1 / &sect;8.2.6.6.3.1; 2025 &sect;8.2.8.1 and &sect;8.2.9.3); NFPA 25 main drain test (2023 and 2026 &sect;13.2.2, pass rule &sect;13.2.2.3; 2020 &sect;13.2.3, &sect;13.2.3.3) and the valve status test after a reopen (2023 and 2026 &sect;13.3.3.4); the NFPA 72 charger rules (&sect;10.6.10.3.1, .3.2, .6.1, .6.2), the standby factor by edition and the DACT attempt rule; the NFPA 13-2022 delivery sections &sect;8.2.3.2, &sect;8.2.3.3, &sect;8.2.3.4, &sect;8.2.3.5 to .6 and &sect;8.2.3.8, which no longer carry a mark; NFPA 72-2025 &sect;26.6.3.3.2(2) for a single path.</p><ul><li>The 2025 acceptance wording for the refill time (&sect;29.2.3.2.4.1: from a search, not verbatim).</li><li>On HOLD: NEC 2026 Chapter 9 Table 8 (a NEC 2026 site shows the 2023 ohms as ASSUMED / VERIFY, never as 2026 code); CAN/ULC-S561, CAN/ULC-S524 and CEC Section 32 (the NAC check is not evaluated on a Canadian build, and the station rule is never shown as Canadian code).</li><li>The NAC method on NFPA 72-2019 and 2022 sites is PRACTICE: 2022 &sect;18.3.7 ends at &sect;18.3.7.2 and 2019 has no &sect;18.3.7.</li><li>NOT FOUND in any NFPA 72 edition held: a low-battery voltage, battery-disconnect supervision, a charger ampere rating, hold-and-send after a DACT failure, and a sentence that says fire alarms latch until a manual reset (&sect;10.14.2 covers supervisory latching only; &sect;23.8.2.9 requires a reset means at the protected premises). FM DS 5-40 is the September 2007 edition and may not be current; NFPA 855-2026 is on HOLD.</li><li>ASSUMED, not in the text held: the annunciation time of a missed DACT test in every edition, and in NFPA 72-2025 the annunciation time for a failed path on multiple paths (&sect;26.6.3.4(1) gives only the 6 h supervision interval).</li><li>NFPA 25-2020: the body text of the valve status test (only the table row is held).</li><li>The 2019 calculation-route paragraphs (&sect;8.2.3.5 to .6).</li><li>The aspirating ranges against the UL Product iQ listing (read from datasheets only).</li></ul>` },
  { id: 'model', t: 'What the simulation does', h: `<p>So you know what to trust:</p><ul><li><b>Hydraulics:</b> a real network solver (global gradient method, the one in EPANET) on your pipe layout, with Hazen-Williams friction, pump curves, check valves and orifice outlets. Loops work. Fittings are a flat 30% equivalent-length adder. Elevation is ignored except tank level.</li>
<li><b>Gas:</b> each dry or preaction system is one ideal-gas volume with choked-orifice flow through leaks and open sprinklers. Trip time and water transit come out of that, not a table.</li><li><b>Fire:</b> t-squared growth, Alpert ceiling-jet temperatures and RTI link heating (the DETACT method). Water at or above design density knocks the fire down; less only slows it.</li>
<li><b>Simplified:</b> one sprinkler per 10 ft tile, no hangers or seismic bracing, one-storey buildings, corrosion as a single number, smoke as one value per room.</li>
<li><b>Simplified in the release logic:</b> the P sensor goes live the first time a valve is set, so a brand-new valve does not latch P during its first air-up. After a mechanical emergency release with every sprinkler closed, the trapped air is not vented, so the pipe sits pressurized and partly filled with no flow. A dead panel&rsquo;s P latch (electric / electric) is lost and read again on restore, not stored. Notification appliances are not modelled.</li>
<li><b>Simplified on purpose in the fire alarm side:</b> the cause-and-effect matrix covers preaction zones only. LocalNAC is a rule read from the signal class, not a circuit. The NAC check is one Class B circuit per panel, end-line-loaded, both conductors counted, 2023 Table 8 ohms, ASSUMED appliance currents; point-to-point, Class A, module voltage adjustment and sync-module loss are not modelled; the NAC alarm current is not added to the battery calculation; there is no NAC signal. NFPA 76 applies by room (a telecom room type); only VEA has a per-room Fire 1 pick. There is no elevator or door device in the game: elevator recall, shunt trip, door hold-open and locked-door devices are outputs and monitor points only and never feed release; a shunt trip is not an EPO hook. Hooks are display-only and never act. The panel shows power troubles at once (inside the 200 s ceiling). The supervising station learns of a dead panel after the path&rsquo;s supervision interval, as one fixed time. AC-fail transmission uses a fixed delay setting, not a random one. The impairment strip is a tag, not a signal. The signal schedule covers the registry&rsquo;s signals; Alert, Action and P classes are owner elections and never dispatch the fire department by themselves. A DACT channel failure is a Sandbox-only fault, and a missed DACT test is annunciated after the ASSUMED 6 h. DACT attempts are counted from the signal&rsquo;s first sight, not a modem model, and the sends after a channel is back are ${DI.DACT_SEND_S} s apart. Hold-and-send keeps a live signal and drops only what has restored; a restoral is always sent; the station is a queue, not a receiver model; the 6 h missed test is text only. Waterflow latches until a panel reset (practice); detectors, stations and the release latches already hold. VEA is a Fire 1-only model (no Alert, Action or Fire 2). The matrix is design intent; live state is shown only in the supervising station queue and the log. Battery: a straight-line voltage curve; one load per panel; the Ah pick is free and a larger battery is not credited with more hours; the charger is amperes &times; ${DI.RECHARGE_H} h with no taper, and costs are ASSUMED; the generator runs exactly 24 h with no fuel model; only the releasing panel is a panel in the game.</li>
<li><b>Simplified on purpose in the air supply:</b> parallel split refill: ${DI.PARALLEL_SPLIT}. The measured clock is informational and runs from the first gas into the closed-up zone; the code check is the largest zone filled alone from 0 psig. The drill report prints the code-check refill time and the measured time on two lines; only the code check is compared with the limit. A refused Finish press is one error per unchanged set of blockers; raw presses are an information line. The operator-step score leaves out the interval the zone is closed up and filling. The AVC and its bypass are two flags: an open bypass drifts the zone to the compressor&rsquo;s cut-out, or to its max discharge or relief, whichever is lower, else ${DI.AVC_BYPASS_PSI} psi, which is not a compressor switch model, and a zone with no AVC is still held at normal; the bypass tamper switch is optional practice. The sizing check adds up the ratings of a zone&rsquo;s sources, a nitrogen generator included. A zone counts as back at normal 3.2 psi under its setpoint (that figure is not a sizing basis). The 60-minute refill limit applies per zone only where every room is a freezer held below 5 F, and the room&rsquo;s own temperature is not held there; sequential refill is a toggle and informational beyond the per-zone check. The return to normal after an air test is ended only by Finish; scoring reads the minimum pressure and the step is split into ${DI.RET_SUBSTEP} s sub-steps while a system drain is letting air out; the trim bleed still snaps to normal in one click, while the system drain runs the real pressure physics; its scoring is a practice result, never a contract goal or star.</li>
<li><b>Simplified on purpose in testing and recovery:</b> the 24 h air test is charged to its test pressure by the game. The recovery rating is informational and separate from contract stars. The main drain test after reopening is step 14 in the contract 5 drill and a tip everywhere else. The &ldquo;confirm 0 psi and no water&rdquo; step is automatic when the conditions hold. Only the system (low-point) drain is scored; the supply-side main drain is optional. A zone with no upstream control valve skips the water-isolation test before a head is replaced. Only the control valve nearest upstream is checked when a zone is reopened. A compressor&rsquo;s own low-air alarm on a separate supply is not modelled.</li>
<li><b>Simplified in water delivery:</b> delivery is judged by the timed trip test only. The calculation / table route is named on the report and not modelled. The inspector&rsquo;s test connection is always present, so the 750 gal trip-test-connection trigger for double interlock is not modelled. On double interlock 750 gal is that trip-test connection trigger, not a maximum volume and not a quick-opening-device exemption: the only size exemption is 500 gal. FM is the 30 s limit only: no FM density, hose or duration.</li></ul><p>It is a trainer for how these systems behave and why the rules exist. It is not a calculation tool for a submittal.</p>` },
];
